// Stage history: Claude's working time and what its turns cost credited to
// the current entry, and what /stage log and /stage time show. Times are
// wall-clock from one entry to the next (the last runs to now) and Claude's
// working time.

import type { ModelUsage } from 'claude-code'

import type { HistoryEntry, Progress, StageId, Workflow } from '../types'
import { cellWidth, stageLabel } from './stages'
import { isDone, stageIds } from './workflow'

export const LOG_DEFAULT = 15

// The entry the work is in: the last, while its stage is the stage the
// work is in; -1 when there is none (untracked, or the stage moved in
// memory by reconcile).
export function currentIndex(p: Progress): number {
  const i = p.history.length - 1

  return i >= 0 && p.stage !== null && p.history[i]!.stage === p.stage ? i : -1
}

// An entry as working time finds it again after another session's copy
// was adopted: its stage and when it began.
export type EntryKey = { stage: StageId; at: number }

export function currentEntry(p: Progress): EntryKey | null {
  const i = currentIndex(p)

  return i < 0 ? null : { stage: p.history[i]!.stage, at: p.history[i]!.at }
}

// What turns cost: dollars, input tokens (uncached, cache read and cache
// write) and output tokens.
export type Cost = NonNullable<HistoryEntry['cost']>

export const NO_COST: Cost = { usd: 0, in: 0, out: 0 }

const hasCost = (c: Cost | undefined): c is Cost => c !== undefined && (c.usd > 0 || c.in > 0 || c.out > 0)

export const addCost = (a: Cost, b: Cost): Cost => ({ usd: a.usd + b.usd, in: a.in + b.in, out: a.out + b.out })

// A turn's token counts as a cost of no dollars; none when it counted nothing.
export function tokensOf(usage: ModelUsage | undefined): Cost {
  if (usage === undefined) return NO_COST
  const n = (x: unknown): number => (typeof x === 'number' && Number.isFinite(x) && x > 0 ? x : 0)

  return { usd: 0, in: n(usage.input_tokens) + n(usage.cache_read_input_tokens) + n(usage.cache_creation_input_tokens), out: n(usage.output_tokens) }
}

// Claude's working time, and what its turns cost, added to the entry they
// were spent in (the last one so named); with none, or nothing above zero
// to add, the progress as it was. The time is added only when above zero,
// the cost only when any of it is.
export function creditAt(p: Progress, key: EntryKey | null, ms: number, cost?: Cost): Progress {
  const i = key === null ? -1 : p.history.findLastIndex(h => h.stage === key.stage && h.at === key.at)
  const isTime = ms > 0
  const isCost = hasCost(cost)
  if (i < 0 || (!isTime && !isCost)) return p

  return {
    ...p,
    history: p.history.map((h, j) => {
      if (j !== i) return h
      const next = isTime ? { ...h, workMs: (h.workMs ?? 0) + Math.round(ms) } : { ...h }
      if (isCost) next.cost = addCost(h.cost ?? NO_COST, cost)

      return next
    }),
  }
}

export function duration(ms: number): string {
  const minutes = Math.floor(Math.max(0, ms) / 60_000)
  if (minutes < 1) return '<1m'
  if (minutes < 60) return `${minutes}m`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours}h ${String(minutes % 60).padStart(2, '0')}m`

  return `${Math.floor(hours / 24)}d ${hours % 24}h`
}

export const ago = (ms: number): string =>
  ms < 60_000 ? 'just now' : ms < 3_600_000 ? `${Math.floor(ms / 60_000)}m ago` : ms < 86_400_000 ? `${Math.floor(ms / 3_600_000)}h ago` : `${Math.floor(ms / 86_400_000)}d ago`

// An entry with the time it lasted: to the next entry, or to now for the
// last (none for Done: sitting there is no work on the feature); running is
// the working time of a turn under way, which counts for the current entry.
type Span = { entry: HistoryEntry; wallMs: number; workMs: number; isLast: boolean; isDone: boolean }

function spansOf(p: Progress, now: number, runningMs: number): Span[] {
  const current = currentIndex(p)

  return p.history.map((entry, i) => {
    const end = p.history[i + 1]?.at ?? now
    const isDoneEntry = isDone(entry.stage)

    return {
      entry,
      wallMs: isDoneEntry ? 0 : Math.max(0, end - entry.at),
      workMs: (entry.workMs ?? 0) + (i === current ? Math.max(0, runningMs) : 0),
      isLast: i === p.history.length - 1,
      isDone: isDoneEntry,
    }
  })
}

const featureOf = (entry: HistoryEntry): string | null => entry.feature ?? null
const featureName = (feature: string | null): string => feature ?? '(no feature)'

// A token count as /stage log shows it: 850, 1.2k, 48k, 1.2M, 25M.
export function tokenCount(n: number): string {
  const r = Math.round(Math.max(0, n))
  if (r < 1000) return String(r)
  const [size, unit] = r < 999_500 ? [1e3, 'k'] : r < 999_500_000 ? [1e6, 'M'] : [1e9, 'B']
  const v = r / size

  return `${v < 9.95 ? v.toFixed(1).replace(/\.0$/, '') : Math.round(v)}${unit}`
}

// A cost as shown: dollars to the cent (rounded here only), then the
// tokens; each left out when zero, so a cost of nothing reads as ''.
export function costText(c: Cost): string {
  const parts: string[] = []
  if (c.usd > 0) parts.push(c.usd < 0.005 ? '<$0.01' : `$${c.usd.toFixed(2)}`)
  if (c.in > 0 || c.out > 0) parts.push(`${tokenCount(c.in)} in, ${tokenCount(c.out)} out`)

  return parts.join(' · ')
}

// isDone: Done's line, which says "done" where the duration would be.
function times(wallMs: number, workMs: number, soFar = false, cost?: Cost, isDone = false): string {
  const spent = cost === undefined ? '' : costText(cost)
  const lasted = isDone ? 'done' : `${duration(wallMs)}${soFar ? ' so far' : ''}`

  return `${lasted} (Claude ${duration(workMs)}${spent === '' ? '' : ` · ${spent}`})`
}
// Columns line up in terminal cells, as the band's text does.
const widest = (texts: string[]): number => texts.reduce((n, t) => Math.max(n, cellWidth(t)), 0)
const pad = (text: string, width: number): string => text + ' '.repeat(Math.max(0, width - cellWidth(text)))

const EMPTY = 'No moves yet: the history starts when the work enters a stage.'
// Under a list that shows a cost: the dollars start at each session's load
// of the mod, so they can fall short of /cost's.
const COST_NOTE = 'Costs count from when stage-toons loaded in each session, so /cost can show more.'
const withCostNote = (lines: string[], spans: Span[]): string[] => (spans.some(s => s.entry.cost !== undefined) ? [...lines, COST_NOTE] : lines)

// /stage log: the last n entries, oldest first, grouped under their feature.
export function logText(w: Workflow, p: Progress, now: number, n: number, runningMs = 0): string {
  const shown = spansOf(p, now, runningMs).slice(-n)
  if (shown.length === 0) return EMPTY
  const labels = shown.map(s => stageLabel(w, s.entry.stage))
  const width = widest(labels)
  const timeWidth = widest(shown.map(s => times(s.wallMs, s.workMs, s.isLast, s.entry.cost, s.isDone)))
  const lines = [`Stage history, last ${shown.length} move${shown.length === 1 ? '' : 's'}:`]
  let group: string | null | undefined
  shown.forEach((s, i) => {
    const feature = featureOf(s.entry)
    if (i === 0 || feature !== group) lines.push(featureName(feature))
    group = feature
    const by = `by ${s.entry.by}${s.entry.via ? `: ${s.entry.via}` : ''}`
    lines.push(`  ${pad(labels[i]!, width)}   ${pad(times(s.wallMs, s.workMs, s.isLast, s.entry.cost, s.isDone), timeWidth)}   ${pad(ago(now - s.entry.at), 8)}   ${by}`)
  })

  return withCostNote(lines, shown).join('\n')
}

// A line's sums; cost only when one of its entries has one.
type Total = { wallMs: number; workMs: number; cost?: Cost }

function add<K>(totals: Map<K, Total>, key: K, s: Span) {
  const t = totals.get(key) ?? { wallMs: 0, workMs: 0 }
  const cost = s.entry.cost === undefined ? t.cost : addCost(t.cost ?? NO_COST, s.entry.cost)
  totals.set(key, { wallMs: t.wallMs + s.wallMs, workMs: t.workMs + s.workMs, ...(cost === undefined ? {} : { cost }) })
}

// /stage time: the kept history's time per feature, the most recent first,
// and per stage, in workflow order and then stages no longer in it.
export function timeText(w: Workflow, p: Progress, now: number, runningMs = 0): string {
  const spans = spansOf(p, now, runningMs)
  if (spans.length === 0) return EMPTY
  const byFeature = new Map<string | null, Total>()
  const lastSeen = new Map<string | null, number>()
  const byStage = new Map<StageId, Total>()
  spans.forEach((s, i) => {
    const key = featureOf(s.entry)
    add(byFeature, key, s)
    lastSeen.set(key, i)
    add(byStage, s.entry.stage, s)
  })
  const features = [...byFeature.keys()].sort((a, b) => lastSeen.get(b)! - lastSeen.get(a)!)
  const ids = stageIds(w)
  const stages = [...ids.filter(id => byStage.has(id)), ...[...byStage.keys()].filter(id => !ids.includes(id))]
  const featureLabels = features.map(featureName)
  const stageLabels = stages.map(id => stageLabel(w, id))
  const width = widest([...featureLabels, ...stageLabels])
  const row = (label: string, t: Total, isDoneRow = false) => `  ${pad(label, width)}   ${times(t.wallMs, t.workMs, false, t.cost, isDoneRow)}`

  return withCostNote([
    'Time per feature:',
    ...features.map((k, i) => row(featureLabels[i]!, byFeature.get(k)!)),
    'Time per stage:',
    ...stages.map((id, i) => row(stageLabels[i]!, byStage.get(id)!, isDone(id))),
    `From the last ${spans.length} move${spans.length === 1 ? '' : 's'}, since ${ago(now - spans[0]!.entry.at)}.`,
  ], spans).join('\n')
}

files.hooks/nowplaying.ts:
// What Spotify plays, as every platform's reader gives it (Clawd DJ), and
// what the mod makes of it: the track, the two-misses rule, the poll's
// pace. Pure: readers.ts has the commands, register.tsx runs them.

export type NowPlaying = { artist: string; title: string; isPlaying: boolean }

// What a script printed (Windows', macOS'): the track, or null for {} (no
// Spotify session), output that isn't the scripts' JSON, or no title.
export function parseNowPlaying(stdout: string): NowPlaying | null {
  let raw: unknown
  try {
    raw = JSON.parse(stdout.trim())
  } catch {
    return null
  }
  if (typeof raw !== 'object' || raw === null) return null
  const { status, artist, title } = raw as Record<string, unknown>
  if (typeof title !== 'string' || title.trim() === '') return null

  return { artist: typeof artist === 'string' ? artist.trim() : '', title: title.trim(), isPlaying: status === 'Playing' }
}

// The track as the now-playing box writes it, and as /stage dj answers it.
export const trackText = (np: NowPlaying): string => (np.artist ? `${np.artist} - ${np.title}` : np.title)
export const trackLine = (np: NowPlaying): string => `♪ ${np.artist ? `${np.artist} – ${np.title}` : np.title}`

// Why a read gave nothing: the command didn't start or ran past its time
// (rejected), it exited with an error (exit), it printed something that
// isn't its answer (output), or macOS's Automation permission is denied
// (denied).
export type ReadFailure = 'rejected' | 'exit' | 'output' | 'denied'
// A finished read: the track, or nothing playing, and what failed if
// anything did.
export type Outcome = { track: NowPlaying | null; failure: ReadFailure | null }

// What the mod has heard of the music: the last track read (kept through a
// pause, and through a read that found none, for the answer), whether the
// DJ picture shows, and how many reads in a row said not playing. The
// picture goes only after two: a skip or a short pause keeps the booth.
export type Music = { track: NowPlaying | null; isPlaying: boolean; misses: number }
export const NO_MUSIC: Music = { track: null, isPlaying: false, misses: 0 }
export const MISSES_TO_STOP = 2

export function heard(h: Music, read: NowPlaying | null): Music {
  if (read?.isPlaying) return { track: read, isPlaying: true, misses: 0 }
  const misses = h.misses + 1

  return { track: read ?? h.track, isPlaying: h.isPlaying && misses < MISSES_TO_STOP, misses }
}

// Whether a read brought another track than the one playing: the scene
// swaps the record then.
export const isNewTrack = (before: Music, after: Music): boolean =>
  before.isPlaying && after.isPlaying && before.track !== null && after.track !== null && trackText(before.track) !== trackText(after.track)

// The poll's pace: a read every 5 s while the area shows, every 30 s while
// it doesn't (the band hidden, collapsed or yielding) and while Clawd
// sleeps with nothing playing. A read may take this long before it counts
// as failed (reads never overlap: the loop awaits each).
export const POLL_MS = 5000
export const SLOW_POLL_MS = 30_000
export const READ_TIMEOUT_MS = 10_000
// /stage dj on reads in its own hook, whose budget (10 s) the read must not
// spend: it may take this long, and the poll catches up after it.
export const COMMAND_READ_MS = 4000

export type PollState = { isAreaShown: boolean; isAsleep: boolean; isPlaying: boolean }

export const nextDelay = (s: PollState): number => (s.isAreaShown && (s.isPlaying || !s.isAsleep) ? POLL_MS : SLOW_POLL_MS)

files.hooks/readers.ts:
// Clawd DJ's readers, one per platform: which platform the session runs
// on (Windows from the cwd; elsewhere uname -sr's answer), and for each
// the command that reads what Spotify plays and what its answer means.
// Every reader ends in the same Outcome, so what follows a read is the
// same everywhere. Pure: register.tsx runs the commands with $.process.run.

import { type Outcome, parseNowPlaying, type ReadFailure } from './nowplaying'
import { base64 } from './pixels'

// Where DJ mode reads: 'linux-missing' is Linux without playerctl, 'wsl'
// Linux under Windows (Spotify plays on the Windows side, out of reach),
// 'unknown' a uname that didn't answer in time.
export type Platform = 'windows' | 'macos' | 'linux' | 'linux-missing' | 'wsl' | 'unknown' | 'none'

// The platform check's commands, each given CHECK_TIMEOUT_MS.
export const UNAME_ARGV: readonly string[] = ['uname', '-sr']
export const PLAYERCTL_VERSION_ARGV: readonly string[] = ['playerctl', '--version']
export const CHECK_TIMEOUT_MS = 2000

// What uname -sr's answer makes the platform: Darwin is macOS; Linux is
// Linux, or WSL when its release names Microsoft. 'linux' still needs
// playerctl's check.
export function platformOfUname(result: { exitCode: number; stdout: string }): Platform {
  if (result.exitCode !== 0) return 'none'
  const text = result.stdout.trim()
  if (text.startsWith('Darwin ')) return 'macos'
  if (text.startsWith('Linux ')) return text.toLowerCase().includes('microsoft') ? 'wsl' : 'linux'

  return 'none'
}

export type ReadResult = { exitCode: number; stdout: string; stderr: string }
// A platform's read: the command, whether the OS may ask the person first
// (macOS's Automation permission), and what its answer means.
export type Reader = { argv: readonly string[]; asksPermission: boolean; outcomeOf: (result: ReadResult) => Outcome }

const NOTHING: Outcome = { track: null, failure: null }

// Windows: the script, for Windows PowerShell 5.1 (powershell.exe;
// PowerShell 7 can't reach the media session). It prints Spotify's session
// as compact JSON, { status, artist, title }, or {} when Spotify has none.
// Spotify names its session after the shortcut it was started from:
// Spotify.exe (the Start menu, Win+R), a name with Spotify in it (the
// Microsoft Store edition), or Chromium's per-user id (a taskbar pin that
// carries it), which every Chromium-embedded app without an id of its own
// shares: that one counts only while a Spotify process runs. Without the
// progress line PowerShell writes a progress record to stderr; without the
// UTF-8 output accented names come garbled.
export const WINDOWS_SCRIPT = String.raw`
$ProgressPreference = 'SilentlyContinue'
[Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
Add-Type -AssemblyName System.Runtime.WindowsRuntime
$asTask = [System.WindowsRuntimeSystemExtensions].GetMethods() | ? { $_.Name -eq 'AsTask' -and $_.GetParameters().Count -eq 1 -and $_.GetParameters()[0].ParameterType.Name -eq 'IAsyncOperation${'`'}1' } | select -First 1
function Await($op, [Type]$t) { $task = $asTask.MakeGenericMethod($t).Invoke($null, @($op)); $task.Wait(-1) | Out-Null; $task.Result }
$null = [Windows.Media.Control.GlobalSystemMediaTransportControlsSessionManager, Windows.Media.Control, ContentType = WindowsRuntime]
$mgr = Await ([Windows.Media.Control.GlobalSystemMediaTransportControlsSessionManager]::RequestAsync()) ([Windows.Media.Control.GlobalSystemMediaTransportControlsSessionManager])
$hasSpotify = [bool](Get-Process -Name Spotify -ErrorAction SilentlyContinue)
$s = $mgr.GetSessions() | ? { $id = $_.SourceAppUserModelId; $id -eq 'Spotify.exe' -or $id -like '*Spotify*' -or ($hasSpotify -and $id -like 'Chromium.*') } | select -First 1
if (-not $s) { '{}'; exit }
$p = Await ($s.TryGetMediaPropertiesAsync()) ([Windows.Media.Control.GlobalSystemMediaTransportControlsSessionMediaProperties])
[pscustomobject]@{ status = "$($s.GetPlaybackInfo().PlaybackStatus)"; artist = $p.Artist; title = $p.Title } | ConvertTo-Json -Compress
`

// What -EncodedCommand reads: the text's UTF-16LE bytes in base64.
export function encodeCommand(text: string): string {
  const bytes = new Uint8Array(text.length * 2)
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i)
    bytes[i * 2] = c & 0xff
    bytes[i * 2 + 1] = c >> 8
  }

  return base64(bytes)
}

export const WINDOWS_ARGV: readonly string[] = ['powershell.exe', '-NoProfile', '-NonInteractive', '-EncodedCommand', encodeCommand(WINDOWS_SCRIPT)]

// A finished read that prints the scripts' JSON (Windows, macOS): the
// track, or nothing playing, and what failed if anything did. {} is no
// failure: Spotify has no session.
export function jsonOutcome(result: { exitCode: number; stdout: string }): Outcome {
  if (result.exitCode !== 0) return { track: null, failure: 'exit' }
  const track = parseNowPlaying(result.stdout)
  if (track !== null) return { track, failure: null }

  return { track: null, failure: result.stdout.trim() === '{}' ? null : 'output' }
}

// macOS: osascript's JavaScript (JXA). running() asks the system, not
// Spotify: no Apple Event, no Automation prompt, and Spotify isn't
// launched (anything asked of Spotify itself would launch it). Stopped
// (nothing loaded) has no track to ask. The status is capitalised to the
// Windows script's spelling, so both print the same JSON.
export const MAC_SCRIPT = `(() => {
  const app = Application('Spotify')
  if (!app.running()) return '{}'
  const state = app.playerState()
  if (state === 'stopped') return '{}'
  const track = app.currentTrack
  return JSON.stringify({ status: state.charAt(0).toUpperCase() + state.slice(1), artist: track.artist(), title: track.name() })
})()`
export const MAC_ARGV: readonly string[] = ['osascript', '-l', 'JavaScript', '-e', MAC_SCRIPT]

// osascript's error codes, as stderr ends them: the Automation permission
// denied (-1743), or needed with no one to ask, as over SSH (-1744);
// Spotify not installed (-2700) or quit between running() and the read
// (-600), which are nothing playing, as Windows' {}.
const DENIED_CODES = ['(-1743)', '(-1744)']
const GONE_CODES = ['(-2700)', '(-600)']

export function macOutcome(result: ReadResult): Outcome {
  if (result.exitCode !== 0 && DENIED_CODES.some(code => result.stderr.includes(code))) return { track: null, failure: 'denied' }
  if (result.exitCode !== 0 && GONE_CODES.some(code => result.stderr.includes(code))) return NOTHING

  return jsonOutcome(result)
}

// Linux: playerctl over MPRIS, Spotify's player only, as three lines:
// status (Playing, Paused, Stopped), artist, title. Lines, not JSON:
// playerctl's format has no escaping. "No player" covers both of
// playerctl's texts the probe met (the spec): No players found, Spotify
// not running, and No player could handle this command, nothing loaded.
export const LINUX_ARGV: readonly string[] = ['playerctl', '--player=spotify', 'metadata', '--format', ['{{status}}', '{{artist}}', '{{title}}'].join('\n')]

export function linuxOutcome(result: ReadResult): Outcome {
  if (result.exitCode !== 0) return result.stderr.includes('No player') ? NOTHING : { track: null, failure: 'exit' }
  const lines = result.stdout.replace(/\r?\n$/, '').split(/\r?\n/)
  if (lines.length < 3) return { track: null, failure: 'output' }
  const [status = '', artist = '', ...rest] = lines
  const title = rest.join(' ').trim()
  if (title === '') return NOTHING

  return { track: { artist: artist.trim(), title, isPlaying: status.trim() === 'Playing' }, failure: null }
}

export const WINDOWS_READER: Reader = { argv: WINDOWS_ARGV, asksPermission: false, outcomeOf: jsonOutcome }
export const MAC_READER: Reader = { argv: MAC_ARGV, asksPermission: true, outcomeOf: macOutcome }
export const LINUX_READER: Reader = { argv: LINUX_ARGV, asksPermission: false, outcomeOf: linuxOutcome }

// The platform's reader, or null where DJ mode can't read.
export function readerFor(platform: Platform): Reader | null {
  if (platform === 'windows') return WINDOWS_READER
  if (platform === 'macos') return MAC_READER

  return platform === 'linux' ? LINUX_READER : null
}

// What macOS's Automation permission keeps from a read: denied, or
// probably asking (a read waits on the prompt until its timeout), which
// only a timeout before any read of the load reached Spotify counts as;
// after one, a timeout is a slow read (a hung Spotify, a busy machine).
export type DjProblem = 'asking' | 'denied' | null

export function problemOf(reader: Reader, failure: ReadFailure | null, hasRead: boolean): DjProblem {
  if (!reader.asksPermission) return null
  if (failure === 'denied') return 'denied'

  return failure === 'rejected' && !hasRead ? 'asking' : null
}

files.hooks/phase.ts:
// What kind of work a tool call is (its phase), what it touched (the
// label beside the phase's badge), and the moments that get a line said:
// all from the tool's name and its arguments, nothing else.

export type Phase = 'search' | 'read' | 'edit' | 'test' | 'build' | 'git' | 'run' | 'web' | 'agents'
export const PHASES: readonly Phase[] = ['search', 'read', 'edit', 'test', 'build', 'git', 'run', 'web', 'agents']

// How long a label may be, with the ~ that marks one cut short (the
// raster's text is ASCII, so no ellipsis).
export const LABEL_MAX = 14

type Args = Record<string, unknown>

const TOOL_PHASES: Record<string, Phase> = {
  Grep: 'search',
  Glob: 'search',
  ToolSearch: 'search',
  Read: 'read',
  NotebookRead: 'read',
  Edit: 'edit',
  Write: 'edit',
  MultiEdit: 'edit',
  NotebookEdit: 'edit',
  WebFetch: 'web',
  WebSearch: 'web',
  Agent: 'agents',
  Task: 'agents',
  Workflow: 'agents',
}

const text = (v: unknown): string => (typeof v === 'string' ? v : '')

// The commands of a shell line, split at && || ; | and newlines (quotes are
// not read: a separator inside one splits too, which only shortens a label).
const commandsOf = (line: string): string[][] =>
  line
    .split(/&&|\|\||[;|\n]/)
    .map(part => part.trim().split(/\s+/).filter(word => word !== ''))
    .filter(words => words.length > 0)

const isAssignment = (word: string) => /^[A-Za-z_][A-Za-z0-9_]*=/.test(word)

// The options of a wrapper that take a value of their own.
const WRAPPERS: Record<string, readonly string[]> = {
  npx: ['-p', '--package'],
  env: ['-u', '--unset', '-C', '--chdir'],
  sudo: ['-u', '-g', '-C', '-h', '-p'],
  nice: ['-n', '--adjustment'],
  timeout: ['-s', '--signal', '-k', '--kill-after'],
  time: ['-f', '--format', '-o', '--output'],
}

// The runners named with a word of their own before the command.
const RUNNERS: Record<string, string> = { uv: 'run', poetry: 'run', pnpm: 'exec', pipenv: 'run' }

// A command's words without what only runs it: environment assignments,
// the wrappers (npx, env, sudo, nice, timeout with its duration, time)
// with their options, and uv run, poetry run, pnpm exec, pipenv run.
function bare(words: readonly string[]): string[] {
  let i = 0
  for (;;) {
    while (i < words.length && isAssignment(words[i]!)) i++
    if (RUNNERS[words[i] ?? ''] !== undefined && words[i + 1] === RUNNERS[words[i]!]) {
      i += 2
      continue
    }
    const wrapper = WRAPPERS[words[i] ?? '']
    if (!wrapper) break
    const isTimeout = words[i] === 'timeout'
    i++
    while (i < words.length && words[i]!.startsWith('-')) i += wrapper.includes(words[i]!) ? 2 : 1
    if (isTimeout) i++
  }

  return words.slice(i)
}

// The first command of a shell line that does something: leading cd's are
// skipped, and what only runs it is stripped.
export function firstCommand(line: string): string[] {
  const commands = commandsOf(line).map(bare)
  const first = commands.find(words => words.length > 0 && words[0] !== 'cd')

  return first ?? commands.find(words => words.length > 0) ?? []
}

const TEST_RUNNERS = new Set(['jest', 'vitest', 'pytest', 'mocha', 'rspec', 'phpunit', 'ctest'])
const TEST_SUBCOMMANDS = new Set(['go', 'cargo', 'dotnet', 'mvn', 'gradle', 'gradlew', './gradlew', 'bun', 'deno'])
const PACKAGE_MANAGERS = new Set(['npm', 'pnpm', 'yarn'])
const BUILD_TOOLS = new Set(['tsc', 'make', 'cmake', 'webpack', 'gradle', 'mvn'])

function isTest(w: readonly string[]): boolean {
  const [a = '', b = '', c = ''] = w
  if (TEST_RUNNERS.has(a)) return true
  if (TEST_SUBCOMMANDS.has(a) && b === 'test') return true
  if (PACKAGE_MANAGERS.has(a) && (b === 'test' || b === 't' || b.startsWith('test:') || (b === 'run' && c.startsWith('test')))) return true
  if (a === 'claude' && b === 'plugin' && c === 'test') return true
  if (a === 'make' && (b === 'test' || b === 'check')) return true
  if ((a === 'tsx' || a === 'node' || a === 'bun') && w.includes('--test')) return true

  return /^python3?$/.test(a) && b === '-m' && c === 'pytest'
}

function isBuild(w: readonly string[]): boolean {
  const [a = '', b = '', c = ''] = w
  if (BUILD_TOOLS.has(a)) return true
  if ((a === 'cargo' || a === 'go' || a === 'dotnet') && b === 'build') return true
  if (PACKAGE_MANAGERS.has(a) || a === 'bun') {
    if (a === 'yarn' && b === '') return true
    if (['ci', 'install', 'i', 'add', 'build'].includes(b)) return true
    if (b === 'run' && c.startsWith('build')) return true
  }
  if (/^pip3?$/.test(a) && b === 'install') return true
  if (a === 'vite' && b === 'build') return true

  return a === 'claude' && b === 'plugin' && c === 'validate'
}

// The phase of a call of the main conversation, or null when it shows no
// badge (a skill, the task tools, the mod's own tool). ownTool: the mod's
// set_stage, an MCP tool that is not web work.
export function phaseOf(tool: string, args: Args, ownTool: string): Phase | null {
  if (tool === 'Bash') {
    const w = firstCommand(text(args.command))
    if (isTest(w)) return 'test'
    if (isBuild(w)) return 'build'
    if (w[0] === 'git' || w[0] === 'gh') return 'git'

    return 'run'
  }
  if (tool.startsWith('mcp__')) return tool === ownTool ? null : 'web'

  return TOOL_PHASES[tool] ?? null
}

// A label cut to LABEL_MAX with a ~, anything outside printable ASCII a ?.
export function labelOf(value: string): string {
  const ascii = value.trim().replace(/[^\x20-\x7e]/g, '?')

  return ascii.length > LABEL_MAX ? `${ascii.slice(0, LABEL_MAX - 1)}~` : ascii
}

const baseName = (path: string) => path.split(/[\\/]/).filter(part => part !== '').at(-1) ?? ''

function hostOf(url: string): string {
  const m = /^[a-z][a-z0-9+.-]*:\/\/([^/?#:]+)/i.exec(url.trim())

  return m ? m[1]! : url
}

// What a call touched, as its badge's label: a file's name, a pattern, a
// command's first two words, a host, a query, an agent's description; ''
// when it names nothing.
export function whatOf(tool: string, args: Args): string {
  switch (tool) {
    case 'Read':
    case 'Edit':
    case 'Write':
    case 'MultiEdit':
      return labelOf(baseName(text(args.file_path)))
    case 'NotebookEdit':
    case 'NotebookRead':
      return labelOf(baseName(text(args.notebook_path) || text(args.file_path)))
    case 'Grep':
    case 'Glob':
      return labelOf(text(args.pattern))
    case 'Bash':
      return labelOf(gitless(firstCommand(text(args.command))).slice(0, 2).join(' '))
    case 'WebFetch':
      return labelOf(hostOf(text(args.url)))
    case 'WebSearch':
      return labelOf(text(args.query))
    case 'Agent':
    case 'Task':
    case 'Workflow':
      return labelOf(text(args.description))
    default:
      return ''
  }
}

// A git command's words without git's global options (-C <dir>, -c k=v,
// --no-pager): git, then its verb and what follows. Other commands as
// given.
function gitless(words: readonly string[]): string[] {
  if (words[0] !== 'git') return [...words]
  let i = 1
  while (i < words.length && words[i]!.startsWith('-')) i += words[i] === '-C' || words[i] === '-c' ? 2 : 1

  return ['git', ...words.slice(i)]
}

// The moments a call says a line at, as it ends: a test run that passed or
// failed, a commit, a push (anywhere in the shell line).
export type Moment = 'test-pass' | 'test-fail' | 'commit' | 'push'

export function momentOf(tool: string, args: Args, isError: boolean): Moment | null {
  if (tool !== 'Bash') return null
  const commands = commandsOf(text(args.command)).map(bare)
  if (isTest(firstCommand(text(args.command)))) return isError ? 'test-fail' : 'test-pass'
  if (isError) return null
  const gitDoes = (verb: string) => commands.some(w => w[0] === 'git' && gitless(w)[1] === verb)
  if (gitDoes('push')) return 'push'

  return gitDoes('commit') ? 'commit' : null
}

files.hooks/pixels.ts:
// A grid of pixels, two to a terminal cell (the upper and lower half
// blocks), packed the way a Raster's cells are: little-endian u32 triplets
// [codePoint, foreground, background], base64. A buffer may also carry
// text: a character in a cell, drawn over the cell's upper pixel.
//
// A buffer may have an origin (ox, oy): where a picture's 48 x 14 core has
// its (0, 0) on a wider or taller area. setPixel and fillRect (and so every
// sprite and Clawd) take the core's coordinates and add it; getPixel, the
// text helpers and everything that works on the whole grid use the
// buffer's own.

export const EMPTY = -1
export const TERMINAL_DEFAULT = 0x01000000

export type Point = { x: number; y: number }
// Per terminal cell (a column, two pixel rows), a character's code point
// (0: none) and its colour.
export type TextLayer = { cp: Int32Array; fg: Int32Array }
export type PixelBuffer = { w: number; h: number; px: Int32Array; text?: TextLayer; ox?: number; oy?: number }

export const hex = (s: string): number => parseInt(s.replace('#', ''), 16)

export const createBuffer = (w: number, h: number, ox = 0, oy = 0): PixelBuffer =>
  ox === 0 && oy === 0 ? { w, h, px: new Int32Array(w * h).fill(EMPTY) } : { w, h, px: new Int32Array(w * h).fill(EMPTY), ox, oy }

// The area's edges in the core's coordinates: the first column past its
// right edge (48 on a bare stage), and its top row (0 on a bare stage,
// above the core's top on a taller area).
export const rightOf = (b: PixelBuffer): number => b.w - (b.ox ?? 0)
export const topOf = (b: PixelBuffer): number => 0 - (b.oy ?? 0)

export function setPixel(b: PixelBuffer, x: number, y: number, color: number): void {
  const xi = Math.round(x) + (b.ox ?? 0)
  const yi = Math.round(y) + (b.oy ?? 0)
  if (color === EMPTY || xi < 0 || yi < 0 || xi >= b.w || yi >= b.h) return
  b.px[yi * b.w + xi] = color
}

export function getPixel(b: PixelBuffer, x: number, y: number): number {
  if (x < 0 || y < 0 || x >= b.w || y >= b.h) return EMPTY

  return b.px[y * b.w + x] ?? EMPTY
}

// How many terminal rows a buffer takes.
export const cellRows = (b: PixelBuffer): number => Math.ceil(b.h / 2)

const textOf = (b: PixelBuffer): TextLayer => {
  const n = b.w * cellRows(b)
  b.text ??= { cp: new Int32Array(n), fg: new Int32Array(n) }

  return b.text
}

// The characters a Raster's cell takes for sure. It refuses the whole
// picture for one that isn't a printable width-1 character of the Basic
// Multilingual Plane, so text sticks to a list known to be: printable
// ASCII; Latin-1's signs and letters (not the no-break space or the soft
// hyphen) and Latin Extended-A and -B (Polish ł and ą among them); the
// Greek and Cyrillic letters (no unassigned code points, no combining
// marks); the dashes and quotes, the ellipsis, and the note.
const GLYPH_RANGES: readonly (readonly [number, number])[] = [
  [0x20, 0x7e],
  [0xa1, 0xac],
  [0xae, 0x24f],
  [0x386, 0x386],
  [0x388, 0x38a],
  [0x38c, 0x38c],
  [0x38e, 0x3a1],
  [0x3a3, 0x3ce],
  [0x400, 0x482],
  [0x48a, 0x4ff],
  [0x2010, 0x201f],
  [0x2026, 0x2026],
  [0x266a, 0x266a],
]
export const isRasterGlyph = (cp: number): boolean => GLYPH_RANGES.some(([from, to]) => cp >= from && cp <= to)
const NO_BREAK_SPACE = 0xa0

// Writes text from a cell on, one character a cell, in a colour: each
// character over the cell's upper pixel, which is its background (the
// lower pixel is not drawn). Composed first (NFC: an e and its accent
// become one é); a no-break space is a space; a character the Raster may
// not take (isRasterGlyph) is a ?, one per character (an emoji's two
// halves are one). Cells outside the buffer are dropped.
export function drawText(b: PixelBuffer, col: number, row: number, text: string, color: number): void {
  if (row < 0 || row >= cellRows(b)) return
  const layer = textOf(b)
  let x = col
  for (const ch of composed(text)) {
    const cp = ch.codePointAt(0)!
    const code = cp === NO_BREAK_SPACE ? 0x20 : cp
    if (x >= 0 && x < b.w) {
      layer.cp[row * b.w + x] = isRasterGlyph(code) ? code : 0x3f
      layer.fg[row * b.w + x] = color
    }
    x++
  }
}

// The text composed (NFC), or as it is where the environment can't.
export function composed(text: string): string {
  try {
    return text.normalize('NFC')
  } catch {
    return text
  }
}

// How many cells drawText takes for a text.
export const textCells = (text: string): number => [...composed(text)].length

// The character in a cell, or null.
export function glyphAt(b: PixelBuffer, col: number, row: number): { cp: number; fg: number } | null {
  const i = row * b.w + col
  const cp = b.text?.cp[i] ?? 0

  return cp === 0 || col < 0 || col >= b.w ? null : { cp, fg: b.text!.fg[i]! }
}

// Clears a cell's two pixels and its character.
export function clearCell(b: PixelBuffer, col: number, row: number): void {
  if (col < 0 || col >= b.w || row < 0 || row >= cellRows(b)) return
  b.px[row * 2 * b.w + col] = EMPTY
  if (row * 2 + 1 < b.h) b.px[(row * 2 + 1) * b.w + col] = EMPTY
  if (b.text) b.text.cp[row * b.w + col] = 0
}

export function fillRect(b: PixelBuffer, x: number, y: number, w: number, h: number, color: number): void {
  for (let dy = 0; dy < h; dy++) for (let dx = 0; dx < w; dx++) setPixel(b, x + dx, y + dy, color)
}

const UPPER = 0x2580
const LOWER = 0x2584
const SPACE = 0x20

export function toWords(b: PixelBuffer): Uint32Array {
  const rows = Math.ceil(b.h / 2)
  const words = new Uint32Array(b.w * rows * 3)
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < b.w; col++) {
      const top = getPixel(b, col, row * 2)
      const bottom = getPixel(b, col, row * 2 + 1)
      // Written by index: a frame allocates no arrays per cell.
      const i = (row * b.w + col) * 3
      const cp = b.text?.cp[row * b.w + col] ?? 0
      if (cp !== 0) {
        words[i] = cp
        words[i + 1] = b.text!.fg[row * b.w + col]!
        words[i + 2] = top === EMPTY ? TERMINAL_DEFAULT : top
      } else if (top === EMPTY && bottom === EMPTY) {
        words[i] = SPACE
        words[i + 1] = TERMINAL_DEFAULT
        words[i + 2] = TERMINAL_DEFAULT
      } else if (bottom === EMPTY) {
        words[i] = UPPER
        words[i + 1] = top
        words[i + 2] = TERMINAL_DEFAULT
      } else if (top === EMPTY) {
        words[i] = LOWER
        words[i + 1] = bottom
        words[i + 2] = TERMINAL_DEFAULT
      } else {
        words[i] = UPPER
        words[i + 1] = top
        words[i + 2] = bottom
      }
    }
  }

  return words
}

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

// The engine's own Uint8Array.prototype.toBase64 when it has one (the
// plugin environment does: about 40 times faster, little garbage), else
// the loop below; both give the same text.
export function base64(bytes: Uint8Array): string {
  const native = (bytes as Uint8Array & { toBase64?: () => string }).toBase64

  return typeof native === 'function' ? native.call(bytes) : base64Loop(bytes)
}

export function base64Loop(bytes: Uint8Array): string {
  let out = ''
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i]!
    const b = bytes[i + 1]
    const c = bytes[i + 2]
    const n = (a << 16) | ((b ?? 0) << 8) | (c ?? 0)
    out += ALPHABET[(n >> 18) & 63]! + ALPHABET[(n >> 12) & 63]!
    out += b === undefined ? '=' : ALPHABET[(n >> 6) & 63]!
    out += c === undefined ? '=' : ALPHABET[n & 63]!
  }

  return out
}

export const encodeCells = (b: PixelBuffer): string => base64(new Uint8Array(toWords(b).buffer))

