// The seating log: the roster's agents at work as helpers at the desk row,
// each with when it walked in and when it got up to leave, and Clawd's walk
// aside and back. Pure: seat() moves the log on to a moment; where
// everyone stands at a moment is worked out from the log alone. A wider
// area seats more helpers (the count fixed for the period when it starts),
// and each helper walks in from the area's right edge as it was when it
// arrived, and out to it, so a resize moves nobody.

import { atWork, type ModelKind, type Roster } from '../agents'

// The fewest seats, on a 48-column area, and the most: one more each 8
// columns past 48.
export const SEATS = 4
export const MAX_SEATS = 8
export const AREA_W = 48
export const seatsFor = (columns: number): number => Math.max(SEATS, Math.min(MAX_SEATS, SEATS + Math.floor((columns - AREA_W) / 8)))
// Each seat's left column.
export const seatX = (seat: number): number => 16 + 8 * seat
// Clawd's column in the idle box (CLAWD_X) and standing aside.
export const CLAWD_HOME = 12
export const CLAWD_ASIDE = 0
// Helpers walk 24 pixels a second on a 48-column area, faster on a wider
// one, so the walk to a seat takes about as long up to about 100 columns
// (48 pixels a second at most); Clawd walks 12; arrivals stamped together
// come half a second apart; a leaving helper hops for 0.3 s first.
export const WALK_SPEED = 24
export const MAX_WALK_SPEED = 48
export const CLAWD_SPEED = 12
export const ARRIVAL_GAP = 500
export const HOP = 300

// edge: the area's width (48 at least) when the helper arrived, where it
// walks in from and out to; x, the column it stands at when that isn't its
// seat's (a spot on the DJ's dance floor).
export type SeatEntry = { agentId: string; seat: number; kind: ModelKind; arrivedAt: number; leftAt: number | null; edge: number; x?: number }
// Where a helper stands once it has walked in.
export const homeX = (e: SeatEntry): number => e.x ?? seatX(e.seat)
// Places other than the desk row's seats: how many there are, and each
// one's column (the DJ's dance floor).
export type Spots = { count: number; x: (seat: number) => number }
// Clawd's walk: from fromX at `at`, toward toX, at CLAWD_SPEED.
export type Walk = { at: number; fromX: number; toX: number }
// seats: how many seats the period has (SEATS until one starts).
export type SeatLog = { entries: SeatEntry[]; queue: string[]; since: number | null; until: number | null; walk: Walk | null; seats: number }

export const EMPTY_LOG: SeatLog = { entries: [], queue: [], since: null, until: null, walk: null, seats: SEATS }

const walkMs = (pixels: number, speed: number) => (Math.abs(pixels) / speed) * 1000
// A helper's walking speed, from its edge.
export const walkSpeed = (e: SeatEntry): number => Math.min(MAX_WALK_SPEED, (WALK_SPEED * e.edge) / AREA_W)

// Where a helper walking in from its edge stands at a moment.
const walkInX = (e: SeatEntry, now: number) => Math.max(homeX(e), e.edge - ((now - e.arrivedAt) / 1000) * walkSpeed(e))
// When a helper reaches its seat, walking in.
export const seatedAt = (e: SeatEntry): number => e.arrivedAt + walkMs(e.edge - homeX(e), walkSpeed(e))
// Whether the helper had sat down when it got up.
const satAt = (e: SeatEntry, at: number) => at >= seatedAt(e)
// Where a leaving helper starts walking out: its seat, or (turned round
// mid walk-in) where it stood.
const outFrom = (e: SeatEntry, leftAt: number) => (satAt(e, leftAt) ? homeX(e) : walkInX(e, leftAt))

// When a leaving helper has walked out of the area and its seat is free.
export function freesAt(e: SeatEntry): number {
  if (e.leftAt === null) return Infinity
  const hop = satAt(e, e.leftAt) ? HOP : 0

  return e.leftAt + hop + walkMs(e.edge - outFrom(e, e.leftAt), walkSpeed(e))
}

export type HelperPose = 'walk-in' | 'seated' | 'hop' | 'walk-out'
export type Helper = { entry: SeatEntry; pose: HelperPose; x: number; stride: number }

// A helper as it stands at a moment, or null before it walks in or after
// it has walked out.
export function helperAt(e: SeatEntry, now: number): Helper | null {
  if (now < e.arrivedAt) return null
  if (e.leftAt === null || now < e.leftAt) {
    if (!satAt(e, now)) return { entry: e, pose: 'walk-in', x: Math.round(walkInX(e, now)), stride: strideAt(now - e.arrivedAt) }

    return { entry: e, pose: 'seated', x: homeX(e), stride: 0 }
  }
  if (now >= freesAt(e)) return null
  const hop = satAt(e, e.leftAt) ? HOP : 0
  if (now < e.leftAt + hop) return { entry: e, pose: 'hop', x: homeX(e), stride: 0 }
  const from = outFrom(e, e.leftAt)
  const gone = now - e.leftAt - hop

  return { entry: e, pose: 'walk-out', x: Math.round(from + (gone / 1000) * walkSpeed(e)), stride: strideAt(gone) }
}

// A step every 125 ms, four to a stride.
const strideAt = (ms: number) => Math.floor(ms / 125) % 4

// Clawd's column at a moment.
export function clawdX(log: SeatLog, now: number): number {
  const w = log.walk
  if (!w) return CLAWD_HOME
  const ms = walkMs(w.toX - w.fromX, CLAWD_SPEED)
  const k = ms === 0 ? 1 : Math.max(0, Math.min(1, (now - w.at) / ms))

  return Math.round(w.fromX + (w.toX - w.fromX) * k)
}

// Whether Clawd is on his way at a moment, and his walk frame.
export function clawdWalking(log: SeatLog, now: number): { facing: number; stride: number } | null {
  const w = log.walk
  if (!w || w.fromX === w.toX) return null
  if (now < w.at || now >= w.at + walkMs(w.toX - w.fromX, CLAWD_SPEED)) return null

  return { facing: Math.sign(w.toX - w.fromX), stride: strideAt(now - w.at) }
}

// The log moved on to `now`: helpers whose agents stopped work get up and
// leave (or, unseen, vanish), seats freed by helpers that walked out go to
// the queue, agents new to the log are stamped when the toon is shown, and
// the waiting period starts and ends. endedAt is when a waiting period
// ended, if one ended in this step: the idle clock restarts there.
// columns: the area's width now, which sets a starting period's seats and
// each newcomer's edge; spots, when given, stand in for the desk row's
// seats (their count for the period, each newcomer's column).
export function seat(log: SeatLog, roster: Roster, now: number, isShown: boolean, columns = AREA_W, spots?: Spots): { log: SeatLog; endedAt: number | null } {
  const working = new Set(atWork(roster).map(a => a.id))
  const freed = log.entries.filter(e => freesAt(e) <= now)
  let entries = log.entries.filter(e => freesAt(e) > now)
  entries = entries.flatMap(e => {
    if (e.leftAt !== null) return isShown ? [e] : []
    if (working.has(e.agentId)) return [e]
    if (!isShown || now < e.arrivedAt) return []

    return [{ ...e, leftAt: now }]
  })
  let queue = log.queue.filter(id => working.has(id))
  if (!isShown && working.size === 0) return { log: EMPTY_LOG, endedAt: log.since === null ? null : now }
  const seats = log.since === null ? (spots?.count ?? seatsFor(columns)) : log.seats
  if (isShown) {
    const known = new Set([...entries.map(e => e.agentId), ...queue])
    queue = [...queue, ...[...working].filter(id => !known.has(id))]
    let last = Math.max(-Infinity, ...entries.map(e => e.arrivedAt))
    while (queue.length > 0) {
      const taken = new Set(entries.map(e => e.seat))
      const free = Array.from({ length: seats }, (_, s) => s).find(s => !taken.has(s))
      if (free === undefined) break
      const agentId = queue.shift()!
      const arrivedAt = Math.max(now, last + ARRIVAL_GAP)
      last = arrivedAt
      entries = [...entries, { agentId, seat: free, kind: roster.get(agentId)?.kind ?? 'unknown', arrivedAt, leftAt: null, edge: Math.max(AREA_W, columns), ...(spots ? { x: spots.x(free) } : {}) }]
    }
  }
  let { since, until, walk } = log
  if (since === null) {
    if (entries.length === 0) return { log: { ...EMPTY_LOG, queue }, endedAt: null }
    since = Math.min(...entries.map(e => e.arrivedAt))
    walk = { at: since, fromX: CLAWD_HOME, toX: CLAWD_ASIDE }
  }
  const draft: SeatLog = { entries, queue, since, until, walk, seats }
  if (entries.length === 0 && queue.length === 0) {
    if (until === null) {
      // The last seat freed: Clawd walks back from that moment.
      const at = freed.length > 0 ? Math.max(...freed.map(freesAt)) : now
      const from = clawdX(draft, at)
      const back: Walk = { at, fromX: from, toX: CLAWD_HOME }
      until = at + walkMs(CLAWD_HOME - from, CLAWD_SPEED)
      walk = back
    }
    if (now >= until) return { log: EMPTY_LOG, endedAt: until }

    return { log: { ...draft, until, walk }, endedAt: null }
  }
  if (until !== null) {
    // A newcomer during the walk back: Clawd turns and walks aside again.
    walk = { at: now, fromX: clawdX(draft, now), toX: CLAWD_ASIDE }
    until = null
  }

  return { log: { entries, queue, since, until, walk, seats }, endedAt: null }
}

files.hooks/area.ts:
// The area below the bar: the band's width (at least the core's 48
// columns, cropped from the left where narrower) by 7 to 9 rows, where the
// demo, the waiting toon or the idle routine plays. Clawd stands at its
// bottom left.

import { IDLE_COLS, IDLE_ROWS } from './idle'
import { EMPTY, type PixelBuffer } from './pixels'
import { type AreaSize, areaBuffer, crop, STAGE_SIZE } from './scene'

// The idle box's top row on an area this many rows tall: it sits at the
// area's bottom-left, so Clawd stands on the scenes' floor.
export const idleTop = (rows: number): number => rows * 2 - IDLE_ROWS * 2

// The box on the area, over the routine's background when it has one: the
// background shows wherever the box draws nothing.
export function placeIdle(box: PixelBuffer, background: PixelBuffer | null = null, size: AreaSize = STAGE_SIZE): PixelBuffer {
  const b = background ? { ...background, px: background.px.slice() } : areaBuffer(size)
  const top = idleTop(size.rows)
  for (let y = 0; y < box.h; y++) {
    for (let x = 0; x < Math.min(box.w, IDLE_COLS); x++) {
      const color = box.px[y * box.w + x]!
      if (color !== EMPTY) b.px[(top + y) * b.w + x] = color
    }
  }

  return b
}

// The area's left part, as wide as the area.
export const cropLeft = (full: PixelBuffer, size: AreaSize): PixelBuffer => crop(full, 0, size.columns)

files.hooks/layer.ts:
// The activity layer, drawn over the stage's scene once it is cut to the
// area's width: above Clawd's head, in the area's top four pixel rows (the
// top two terminal rows), a badge for what Claude is doing, its label, and
// a speech bubble. The whole layer is kept inside the area.

import { clearCell, composed, drawText, type PixelBuffer, setPixel, textCells } from './pixels'
import { drawSprite, type Sprite } from './scene'
import { C } from './scenes/kit'
import type { Phase } from './phase'
import { type Layer, PUFFS_S } from './work'

export const BADGE_W = 5
export const BADGE_H = 4
// The terminal rows of the bubble and the label.
const BUBBLE_ROW = 0
const LABEL_ROW = 1

const icon = (palette: Record<string, number>, rows: string[]): Sprite => ({ palette, frames: [rows] })

// Each phase's icon, 5 x 4 pixels, in the scene kit's colours.
export const BADGES: Record<Phase, Sprite> = {
  search: icon({ g: C.gray, b: C.glass, w: C.wood }, ['.gg..', 'gbbg.', '.ggw.', '...ww']),
  read: icon({ w: C.paper, l: C.paperShade, d: C.woodDark }, ['ww.ww', 'wldlw', 'wwdww', '.ddd.']),
  edit: icon({ y: C.gold, r: C.red, g: C.gray }, ['...yr', '..yy.', '.yy..', 'g....']),
  test: icon({ g: C.glass, l: C.liquid }, ['.g.g.', '.glg.', '.glg.', '..g..']),
  build: icon({ d: C.gray, w: C.wood }, ['dddd.', 'dddd.', '.w...', '.w...']),
  git: icon({ G: C.green, l: C.gray }, ['G...G', 'l...l', '.l.l.', '..G..']),
  run: icon({ g: C.green }, ['g....', '.g...', 'g....', '..ggg']),
  web: icon({ b: C.blue, g: C.green }, ['.bgb.', 'bggbb', 'bbbgb', '.bbb.']),
  agents: icon({ b: C.blue, d: C.ink }, ['.bbb.', 'bdbdb', 'bbbbb', 'b.b.b']),
}

// The thought puffs: a dot, a small puff, a cloud, one more each PUFFS_S,
// held a beat with all three, then again.
const PUFFS: [number, number][][] = [
  [[0, 3]],
  [
    [1, 1],
    [2, 1],
    [1, 2],
    [2, 2],
  ],
  [
    [3, 0],
    [4, 0],
    [3, 1],
    [4, 1],
  ],
]

function drawPuffs(b: PixelBuffer, x: number, t: number) {
  const shown = Math.min(3, 1 + (Math.floor((t * 1000) / (PUFFS_S * 1000)) % 4))
  PUFFS.slice(0, shown).forEach((puff, i) => {
    for (const [dx, dy] of puff) setPixel(b, x + dx, dy, i === 2 ? C.white : C.paperShade)
  })
}

// Text cut to fit cells, with a ~ for what was cut, counted as drawText
// draws it: composed, a cell a code point.
function fitText(text: string, cells: number): string {
  const chars = [...composed(text)]
  if (cells <= 0) return ''

  return chars.length <= cells ? chars.join('') : `${chars.slice(0, Math.max(0, cells - 1)).join('')}~`
}

// Draws the layer over an area of b.w columns, the hero's head centred at
// column headX (in the area's own columns). The badge's left edge is at
// headX - 2; the label (or the bubble, which takes its place) one cell to
// its right, or the bubble at headX with no badge; all moved left as far as
// it takes to fit. hasTail false leaves out the bubble's tail (pixel row 2),
// for a head that reaches that row.
export function drawLayer(b: PixelBuffer, layer: Layer, headX: number, hasTail = true): void {
  const hasBadge = layer.badge !== null
  const text = layer.bubble ?? layer.what
  const isBubble = layer.bubble !== null
  const badgeCells = hasBadge ? BADGE_W + 1 : 0
  const room = b.w - badgeCells - (isBubble ? 2 : 0)
  const shown = fitText(text, room)
  const shownCells = shown === '' ? 0 : textCells(shown) + (isBubble ? 2 : 0)
  const total = (hasBadge ? BADGE_W : 0) + (shownCells > 0 ? (hasBadge ? 1 : 0) + shownCells : 0)
  let left = Math.round(hasBadge ? headX - 2 : headX)
  left = Math.max(0, Math.min(left, b.w - total))
  if (layer.badge === 'thinking') drawPuffs(b, left, layer.t)
  else if (layer.badge !== null) drawSprite(b, BADGES[layer.badge], 0, left, 0)
  if (shown === '') return
  const at = left + badgeCells
  if (!isBubble) {
    for (let i = 0; i < shownCells; i++) clearCell(b, at + i, LABEL_ROW)
    drawText(b, at, LABEL_ROW, shown, C.paperShade)

    return
  }
  for (let i = 0; i < shownCells; i++) {
    clearCell(b, at + i, BUBBLE_ROW)
    setPixel(b, at + i, BUBBLE_ROW * 2, C.paper)
    setPixel(b, at + i, BUBBLE_ROW * 2 + 1, C.paper)
  }
  drawText(b, at + 1, BUBBLE_ROW, shown, C.ink)
  // The tail, under the bubble's first cell.
  if (hasTail) setPixel(b, at, BUBBLE_ROW * 2 + 2, C.paper)
}

files.hooks/waiting/index.ts:
// The waiting toon: while Claude waits on agents, Clawd stands aside with a
// cup and watches a row of helpers, one per agent at work, each in its
// model's colour, at one of the waiting scenes (WAITING_SCENES). Drawn on
// the area (its 48 x 14 core at the bottom left, the scene's set running
// on to the right edge) from the seat log, the scene and the time alone.

import { drawClawd, EYE_DARK, MONOCLE } from '../clawd'
import { fillRect, type PixelBuffer, setPixel } from '../pixels'
import { type AreaSize, areaBuffer, CLAWD_TOP, drawSprite, STAGE_SIZE } from '../scene'
import { C, every } from '../scenes/kit'
import { BUILDING } from './building'
import { CONVEYOR } from './conveyor'
import type { WaitingSceneId } from './deal'
import { HELPER_COLORS, type WaitingCtx, type WaitingScene } from './draw'
import { LAPTOPS } from './laptops'
import { ROWING } from './rowing'
import { clawdWalking, clawdX, type Helper, helperAt, type SeatLog } from './seats'

export { FALLBACK_WAITING, isWaitingScene, WAITING_SCENE_IDS, type WaitingSceneId } from './deal'
export { HELPER_COLORS } from './draw'
export { LAPTOP, LAPTOP_LIGHT, SPARK } from './laptops'

// The repeating motions' periods all divide this many seconds.
export const WAITING_BEAT = 6
export const CUP = C.white
export const STEAM = C.glass

export const WAITING_SCENES: Record<WaitingSceneId, WaitingScene> = {
  laptops: LAPTOPS,
  building: BUILDING,
  rowing: ROWING,
  conveyor: CONVEYOR,
}

// A walking helper's top row: it stands on the bottom row.
export const WALKING_TOP = 9

// The walking helper, facing right; mirrored, facing left. Two strides.
const WALKING = [
  ['.MMMMM.', '..MEME.', 'MMMMMMM', '.MMMMM.', '.M...M.'],
  ['.MMMMM.', '..MEME.', 'MMMMMMM', '.MMMMM.', '..M.M..'],
]

export function drawWalker(b: PixelBuffer, h: Helper) {
  const color = HELPER_COLORS[h.entry.kind]
  const isLeft = h.pose === 'walk-in'
  drawSprite(b, { palette: { M: color, E: EYE_DARK }, frames: WALKING }, h.stride, h.x, WALKING_TOP, isLeft)
  if (h.entry.kind === 'fable') setPixel(b, isLeft ? h.x + 1 : h.x + 5, WALKING_TOP + 1, MONOCLE)
}

const SIP_FROM = 4
const SIP_TO = 5

function drawClawdAside(b: PixelBuffer, log: SeatLog, now: number, t: number) {
  const walking = clawdWalking(log, now)
  const x = clawdX(log, now)
  if (walking) {
    drawClawd(b, x, CLAWD_TOP, { pose: 'walk', stride: walking.stride, facing: walking.facing, arms: { left: 'down', right: 'out' } })
    drawCup(b, x, false, t)

    return
  }
  const isSipping = t % WAITING_BEAT >= SIP_FROM && t % WAITING_BEAT < SIP_TO
  const isBlinking = t % 3 < 0.15
  // He looks along the row for 1.5 s, then ahead for 1.5 s.
  const glance = every(t, 1.5) % 2 === 0 ? 1 : 0
  drawClawd(b, x, CLAWD_TOP, {
    eyes: isSipping ? 'closed' : 'open',
    isBlinking,
    look: { x: isSipping ? 0 : glance, y: 0 },
    arms: { left: 'down', right: isSipping ? 'up' : 'out' },
  })
  drawCup(b, x, isSipping, t)
}

// The cup on Clawd's right claw (held out, or raised to sip), steam rising
// from it while it is down.
function drawCup(b: PixelBuffer, x: number, isRaised: boolean, t: number) {
  if (isRaised) {
    fillRect(b, x + 12, CLAWD_TOP - 2, 2, 2, CUP)

    return
  }
  fillRect(b, x + 14, CLAWD_TOP, 2, 2, CUP)
  setPixel(b, x + 14 + (every(t, 0.5) % 2), CLAWD_TOP - 1, STEAM)
}

// The frame: the scene under the helpers, the seated and hopping helpers
// as the scene draws them, the scene over them, Clawd, then the walkers.
export function waitingFrame(log: SeatLog, now: number, scene: WaitingSceneId = 'laptops', size: AreaSize = STAGE_SIZE): PixelBuffer {
  const b = areaBuffer(size)
  const t = log.since === null ? 0 : (now - log.since) / 1000
  const helpers = log.entries.flatMap(e => {
    const h = helperAt(e, now)

    return h ? [h] : []
  })
  const seated = helpers.filter(h => h.pose === 'seated').sort((a, b2) => a.entry.seat - b2.entry.seat)
  const ctx: WaitingCtx = { t, now, log, helpers, seated }
  const drawn = WAITING_SCENES[scene]
  drawn.under?.(b, ctx)
  for (const h of helpers) if (h.pose === 'seated' || h.pose === 'hop') drawn.helper(b, h, ctx)
  drawn.over?.(b, ctx)
  drawClawdAside(b, log, now, t)
  for (const h of helpers) if (h.pose === 'walk-in' || h.pose === 'walk-out') drawWalker(b, h)

  return b
}

