// Blueprint: Clawd draws a plan on a drafting board, line by line, and
// looks it over. On a wider area, rolled blueprints stand in a bin past
// the board, and finished sheets are pinned up in a row to the edge.

import { fillRect, type PixelBuffer, setPixel } from '../pixels'
import { CLAWD_TOP, type Scene } from '../scene'
import { blinking, C, every, still } from './kit'
import { tileOn, WINGS_X } from './wings'

const LOOP = 6
const DRAW_FOR = 5

// The plan's pixels in the order they are drawn: the outline, then a wall
// with a doorway.
const PLAN: [number, number][] = []
for (let x = 28; x <= 40; x++) PLAN.push([x, 4])
for (let y = 5; y <= 10; y++) PLAN.push([40, y])
for (let x = 39; x >= 28; x--) PLAN.push([x, 10])
for (let y = 9; y >= 5; y--) PLAN.push([28, y])
for (let y = 5; y <= 7; y++) PLAN.push([34, y])

// The wings: a bin of rolled blueprints (each roll's top a paler end),
// then pinned sheets every SHEET_EVERY columns, each with its own plan.
const BIN_X = WINGS_X + 2
const ROLLS: [number, number][] = [
  [1, 6],
  [2, 4],
  [3, 7],
  [4, 5],
]
const SHEETS_X = BIN_X + 10
const SHEET_EVERY = 12

function wings(b: PixelBuffer) {
  for (const [dx, top] of ROLLS) {
    fillRect(b, BIN_X + dx, top, 1, 9 - top, C.blue)
    setPixel(b, BIN_X + dx, top, C.glass)
  }
  fillRect(b, BIN_X, 9, 6, 5, C.wood)
  fillRect(b, BIN_X, 9, 6, 1, C.woodDark)
  tileOn(b, SHEETS_X, SHEET_EVERY, (x, k) => {
    fillRect(b, x, 5, 7, 6, C.blue)
    // A room's outline in a paler blue than the plan Clawd draws, so the
    // wings stay quiet, and on every other sheet a wall across it.
    fillRect(b, x + 1, 6, 5, 1, C.glass)
    fillRect(b, x + 1, 9, 5, 1, C.glass)
    fillRect(b, x + 1, 7, 1, 2, C.glass)
    fillRect(b, x + 5, 7, 1, 2, C.glass)
    if (k % 2 === 1) setPixel(b, x + 3, 7, C.glass)
    setPixel(b, x + 3, 4, C.red)
  })
}

export const blueprint: Scene = {
  id: 'blueprint',
  loop: LOOP,
  still: 4.25,
  fadesAtLoop: true,
  focusX: 28,
  backdrop: b => {
    fillRect(b, 26, 2, 17, 11, C.blue)
    fillRect(b, 27, 13, 1, 1, C.woodDark)
    fillRect(b, 41, 13, 1, 1, C.woodDark)
    wings(b)
  },
  actors: [
    {
      kind: 'clawd',
      isHero: true,
      at: still(10, CLAWD_TOP),
      look: t => ({ isBlinking: blinking(t, 0.7), look: { x: 1, y: 0 }, arms: { left: 'down', right: t < DRAW_FOR && every(t, 0.2) % 2 === 0 ? 'out' : 'down' } }),
    },
  ],
  front: (b, t) => {
    const drawn = Math.min(PLAN.length, Math.floor((t / DRAW_FOR) * PLAN.length) + 1)
    for (const [x, y] of PLAN.slice(0, drawn)) setPixel(b, x, y, C.white)
  },
}

files.hooks/scenes/bowling.ts:
// Bowling: one of Claude testing's scenes. Clawd swings a ball back and
// bowls it down a lane that runs across the width; it rolls the length of
// the lane and crashes into the pins at the far end, which fly and fall,
// and a green tick lights up over the pin deck while Clawd cheers. Behind,
// quiet and dim: the alley's back wall, a score screen over every lane's
// length, and the masking panel over the pins. On a wider area the lane is
// longer, up to 150 columns, the ball rolling at the same speed; the loop
// fades in the next ball in Clawd's claw and the pins standing again.

import { CLAWD_W } from '../clawd'
import { fillRect, type PixelBuffer, setPixel } from '../pixels'
import { type Area, areaOf, CLAWD_TOP, drawSprite, type Scene, type Sprite } from '../scene'
import { blinking, C, every, lerp, reach, still } from './kit'
import { eachColumn, eachItem, fade } from './layers'

const LOOP = 9
const CLAWD_X = 4
// The swing: the ball back behind Clawd, then forward and let go on the
// lane at RELEASE.
const BACKSWING = 0.5
const RELEASE = 1.2
// The ball's speed down the lane, columns a second.
const SPEED = 36
// The pins' fall after the hit, the tick's moment after it, and the cheer.
const FALL = 1.1
const TICK_AFTER = 0.5
const CHEER = 1.6

// The lane: its surface rows (the far gutter's edge, the boards), the
// ball's bottom row, and where the pin deck starts: as far as the lane
// reaches, 150 columns at most, short of the edge by the deck's width.
const LANE_TOP = 11
const FLOOR = 13
const BALL_START = CLAWD_X + CLAWD_W + 1
// The ball held at Clawd's side, on the floor by his claw.
const HOLD_X = CLAWD_X + CLAWD_W
const DECK_W = 14
const MAX = 150
const deckOf = (area: Area) => BALL_START + 6 + reach(area, BALL_START + 6, MAX, DECK_W + 2)
// When the ball reaches the pins on an area: at SPEED, but never in less
// than MIN_ROLL seconds, so a short lane's roll can still be followed.
const MIN_ROLL = 1.6
const rollOf = (area: Area) => Math.max(MIN_ROLL, (deckOf(area) - 1 - BALL_START) / SPEED)
const hitOf = (area: Area) => RELEASE + rollOf(area)

const BOARD = fade(C.wood, 0.45)
const BOARD_DARK = fade(C.wood, 0.58)
const GUTTER = fade(C.darkGray, 0.4)
const ARROW = fade(C.gold, 0.6)
const DECK = fade(C.paperShade, 0.62)
const WALL = fade(C.skyShade, 0.88)
const WALL_LINE = fade(C.skyShade, 0.8)
const SCREEN = fade(C.blue, 0.82)
const SCREEN_EDGE = fade(C.gray, 0.78)
const DIGIT = fade(C.paper, 0.7)
const MASK = fade(C.red, 0.78)
const MASK_EDGE = fade(C.gold, 0.74)

// The ball, rolling: its finger holes turn with it (four frames).
const BALL: Sprite = {
  palette: { b: C.blue, h: C.ink, s: C.glass },
  frames: [
    ['.bb.', 'bsbb', 'bhhb', '.bb.'],
    ['.bb.', 'bshb', 'bbhb', '.bb.'],
    ['.bb.', 'bbbb', 'bhhb', '.hb.'],
    ['.hb.', 'bhbb', 'bbbb', '.bb.'],
  ],
}
// A pin standing, tilting and lying; the back row's a shade dimmer.
const PIN_PAL = { w: C.white, r: C.red }
const PIN_BACK_PAL = { w: C.paperShade, r: fade(C.red, 0.3) }
const PIN_UP = ['.w.', 'www', '.r.', 'www', 'www']
const PIN_TILT = ['..w..', '.ww..', '.rw..', 'www..', 'ww...']
const PIN_DOWN = ['.....', '.....', 'w....', 'wwrww', '.wwww']

// The pins at the deck's columns: front row on the floor, back rows a
// row higher and behind; each flies off its own way at the hit (dx
// columns, rising to height, landing at its own moment).
type Pin = { dx: number; row: number; isBack: boolean; fly: number; height: number; land: number }
const PINS: Pin[] = [
  { dx: 7, row: 0, isBack: true, fly: 3, height: 4, land: 0.8 },
  { dx: 10, row: 0, isBack: true, fly: 1, height: 3, land: 0.7 },
  { dx: 4, row: 0, isBack: true, fly: 4, height: 5, land: 0.9 },
  { dx: 1, row: 1, isBack: false, fly: 3, height: 3, land: 0.6 },
  { dx: 5, row: 1, isBack: false, fly: 5, height: 6, land: 1 },
  { dx: 9, row: 1, isBack: false, fly: 2, height: 2, land: 0.5 },
]
// The tick over the deck.
const BIG_TICK: Sprite = { palette: { g: C.green }, frames: [['.....gg', '....gg.', 'gg.gg..', '.ggg...', '..g....']] }

// Where the ball is at t: in Clawd's claws on the swing, on the lane after
// the release, gone into the pit after the hit. Its left column and top
// row, or null.
function ballAt(t: number, area: Area): { x: number; y: number } | null {
  if (t < BACKSWING) return { x: HOLD_X, y: FLOOR - 3 }
  if (t < RELEASE - 0.35) {
    // Back behind him, raised.
    const k = (t - BACKSWING) / (RELEASE - 0.35 - BACKSWING)
    return { x: Math.round(lerp(HOLD_X, CLAWD_X - 3, k * 2)), y: Math.round(lerp(FLOOR - 3, FLOOR - 7, k)) }
  }
  if (t < RELEASE) {
    // Swung forward and down to the lane.
    const k = (t - (RELEASE - 0.35)) / 0.35
    return { x: Math.round(lerp(CLAWD_X - 3, BALL_START, k)), y: Math.round(lerp(FLOOR - 7, FLOOR - 3, k)) }
  }
  const hit = hitOf(area)
  if (t >= hit + 0.15) return null
  return { x: Math.round(lerp(BALL_START, deckOf(area) - 1, (t - RELEASE) / rollOf(area))), y: FLOOR - 3 }
}

const isAfterHit = (t: number, area: Area) => t >= hitOf(area)
const isCheering = (t: number, area: Area) => t >= hitOf(area) + TICK_AFTER && t < hitOf(area) + TICK_AFTER + CHEER

// The alley behind: the back wall and its rail, a score screen every 40
// columns hanging from the area's top with a struck "X" glowing on it,
// and over the pin deck the masking panel.
function drawAlley(b: PixelBuffer, t: number) {
  const area = areaOf(b)
  fillRect(b, area.left, area.top, area.right - area.left, LANE_TOP - area.top, WALL)
  // A dado rail along the wall, at the pins' heads.
  fillRect(b, area.left, 7, area.right - area.left, 1, WALL_LINE)
  const deck = deckOf(area)
  eachItem(b, 0, 40, 26, x => {
    if (x + 12 > deck - 2) return
    const top = area.top + 1
    fillRect(b, x, top, 12, 5, SCREEN_EDGE)
    fillRect(b, x + 1, top + 1, 10, 3, SCREEN)
    // The frames' marks: a strike "X" in each.
    for (let f = 0; f < 3; f++) {
      const fx = x + 2 + f * 3
      setPixel(b, fx, top + 1, DIGIT)
      setPixel(b, fx + 1, top + 2, DIGIT)
      setPixel(b, fx, top + 3, DIGIT)
      setPixel(b, fx + 2, top + 1, DIGIT)
      setPixel(b, fx + 2, top + 3, DIGIT)
    }
  })
  // The masking panel over the deck, down to the pins' heads.
  fillRect(b, deck - 1, area.top, DECK_W + 1, 4 - area.top, MASK)
  fillRect(b, deck - 1, 4, DECK_W + 1, 1, MASK_EDGE)
  // A light under the panel, on the deck: stronger once the tick is up.
  const isLit = t >= hitOf(area) + TICK_AFTER
  fillRect(b, deck, 5, DECK_W - 1, LANE_TOP - 5, isLit ? fade(C.green, 0.85) : fade(C.paper, 0.9))
}

// The lane: the far gutter's edge, boards running its length, the aiming
// arrows a third of the way down, and the pin deck at the far end.
function drawLane(b: PixelBuffer) {
  const area = areaOf(b)
  const deck = deckOf(area)
  eachColumn(b, 0, 7, (x, u) => {
    setPixel(b, x, LANE_TOP, GUTTER)
    for (let y = LANE_TOP + 1; y <= FLOOR; y++) setPixel(b, x, y, x >= deck - 1 ? DECK : (y + u) % 3 === 0 ? BOARD_DARK : BOARD)
  })
  // The arrows, a row of little chevrons, short of the deck.
  const arrows = Math.round(lerp(BALL_START + 4, deck, 0.3))
  for (let i = 0; i < 3 && arrows + i * 3 + 1 < deck - 1; i++) {
    setPixel(b, arrows + i * 3, LANE_TOP + 2, ARROW)
    setPixel(b, arrows + i * 3 + 1, LANE_TOP + 1, ARROW)
  }
}

// The pins: standing until the hit, then each tumbles off its own way and
// lies where it lands; the dimmer back row first, the front row over it.
function drawPins(b: PixelBuffer, t: number) {
  const area = areaOf(b)
  const deck = deckOf(area)
  const k = t - hitOf(area)
  for (const pin of [...PINS].sort((p, q) => Number(q.isBack) - Number(p.isBack))) {
    const palette = pin.isBack ? PIN_BACK_PAL : PIN_PAL
    const baseY = FLOOR - 4 - (pin.isBack ? 1 : 0)
    if (k < 0) {
      drawSprite(b, { palette, frames: [PIN_UP] }, 0, deck + pin.dx, baseY)
      continue
    }
    const u = Math.min(1, k / (FALL * pin.land))
    const x = deck + pin.dx + Math.round(pin.fly * u)
    const y = baseY - Math.round(Math.sin(u * Math.PI) * pin.height)
    const frame = u >= 1 ? PIN_DOWN : PIN_TILT
    drawSprite(b, { palette, frames: [frame] }, 0, x, y)
  }
  // A few splinters of white at the hit.
  if (k >= 0 && k < 0.3) {
    for (let i = 0; i < 4; i++) setPixel(b, deck + 2 + i * 3, FLOOR - 6 - (i % 2) * 2 - Math.floor(k * 10), C.white)
  }
}

export const bowling: Scene = {
  id: 'bowling',
  loop: LOOP,
  still: RELEASE + 0.9,
  fadesAtLoop: true,
  // A narrow raster keeps Clawd and the ball's release in view.
  focusX: 15,
  backdrop: (b, t) => {
    drawAlley(b, t)
    drawLane(b)
  },
  actors: [
    { kind: 'prop', z: -1, draw: drawPins },
    {
      kind: 'clawd',
      isHero: true,
      at: still(CLAWD_X, CLAWD_TOP),
      look: (t, area) => {
        const isSwinging = t >= BACKSWING && t < RELEASE
        const isWatching = t >= RELEASE && !isAfterHit(t, area)

        return {
          pose: isCheering(t, area) && every(t, 0.25) % 2 === 0 ? 'jump' : 'stand',
          facing: 1,
          eyes: isCheering(t, area) ? 'wide' : 'open',
          isBlinking: !isSwinging && !isWatching && !isCheering(t, area) && blinking(t, 0.4),
          look: { x: 1, y: 0 },
          arms: isCheering(t, area)
            ? { left: 'up', right: 'up' }
            : t < BACKSWING
              ? { left: 'down', right: 'down' }
              : t < RELEASE - 0.35
                ? { left: 'out', right: 'down' }
                : t < RELEASE + 0.3
                  ? { left: 'down', right: 'out' }
                  : { left: 'down', right: 'down' },
        }
      },
    },
    {
      kind: 'prop',
      // Behind Clawd on the swing, so it passes behind him; on the lane
      // and the tick, in front.
      z: t => (t < RELEASE ? -1 : 1),
      draw: (b, t) => {
        const area = areaOf(b)
        const at = ballAt(t, area)
        if (at) drawSprite(b, BALL, t < RELEASE ? 0 : every(t, 0.06), at.x, at.y)
        if (t >= hitOf(area) + TICK_AFTER) drawSprite(b, BIG_TICK, 0, deckOf(area) + 3, area.top < 0 ? -1 : 0)
      },
    },
  ],
}

files.hooks/scenes/bricklaying.ts:
// Bricklaying: Clawd lays a wall three courses high, bay by bay, from
// column 6 towards the area's right edge, walking right just past its
// growing end with the wall on his left, his hammer at the end; then he
// cheers, and the loop fades in a bare floor. Behind, quiet and dim: slow clouds, two skylines (far
// towers; nearer blocks with a few lit windows that change), and on a wide
// area a tower crane whose trolley creeps along its jib.

import { CLAWD_W, clawdAnchors } from '../clawd'
import { fillRect, type PixelBuffer, rightOf, setPixel, topOf } from '../pixels'
import { type Area, areaOf, CLAWD_TOP, type Scene } from '../scene'
import { blinking, C, lerp, reach, hash as seededHash } from './kit'
import { eachItem, fade, type LayerSpec, mix, scrolled, wrap } from './layers'

// Only the clouds scroll; the skylines and the crane stand still.
export const LAYERS = {
  clouds: { speed: 0.3, fade: 0.84 },
} as const satisfies Record<string, LayerSpec>

const LOOP = 16
const BUILD = 13.5
const WALL_X = 6
const BAY = 4
// How far the wall reaches: up to 150 columns, and short of the edge by
// Clawd's width and the columns he stands past its end.
const MAX = 150
// From the wall's end to Clawd's left column: his left claw, struck out,
// reaches back to it.
const PAST_END = 3
const MARGIN = CLAWD_W + PAST_END

const CLOUD = fade(C.sky, LAYERS.clouds.fade)
const FAR_CITY = fade(C.skyShade, 0.9)
const FAR_CITY_EDGE = fade(C.skyShade, 0.86)
const CITY = fade(C.skyShade, 0.8)
const CITY_EDGE = fade(C.skyShade, 0.72)
const WINDOW = fade(C.gold, 0.72)
const CRANE = fade(C.gold, 0.6)
const CRANE_DARK = fade(C.gold, 0.75)
const CABLE = fade(C.gray, 0.55)
const BRICK_SHADE = mix(C.brick, C.ink, 0.22)

// The wall's bays on an area: as many whole bays as it reaches.
const baysOn = (area: Area) => Math.floor(reach(area, WALL_X, MAX, MARGIN) / BAY)
// How many bricks are down at t: three a bay (bottom, middle, top).
const laidAt = (t: number, area: Area) => Math.min(baysOn(area) * 3, Math.floor((t / BUILD) * baysOn(area) * 3))
const isDone = (t: number) => t >= BUILD
// Clawd's left column: just past the wall's growing end.
const clawdX = (t: number, area: Area) => Math.round(WALL_X + Math.min(1, t / BUILD) * baysOn(area) * BAY + PAST_END)
const isStriking = (t: number) => !isDone(t) && Math.floor(t * 8) % 2 === 1

// A small hash, for the skylines' buildings and the bricks' shades.
const hash = (n: number) => seededHash(n, 7)

type Skyline = { seed: number; top: number; spread: number; body: number; roof: number; hasWindows: boolean; wide: number; gap: number }
const FAR_SKYLINE: Skyline = { seed: 40, top: -2, spread: 5, body: FAR_CITY, roof: FAR_CITY_EDGE, hasWindows: false, wide: 5, gap: 9 }
const NEAR_SKYLINE: Skyline = { seed: 7, top: 4, spread: 3, body: CITY, roof: CITY_EDGE, hasWindows: true, wide: 9, gap: 5 }

// A row of buildings from the area's left edge to its right: widths, gaps
// and roofs from the hash, roofs between rows top and top + spread; an
// antenna or a water tank on a few; a lit window or two on the nearer row,
// some changing every few seconds.
function drawSkyline(b: PixelBuffer, t: number, s: Skyline) {
  let x = areaOf(b).left - 4 + Math.floor(hash(s.seed) * 6)
  for (let i = s.seed; x < rightOf(b); i++) {
    const w = s.wide - 3 + Math.floor(hash(i) * 6)
    const y0 = s.top + Math.floor(hash(i + 100) * (s.spread + 1))
    fillRect(b, x, y0, w, 14 - y0, s.body)
    fillRect(b, x, y0, w, 1, s.roof)
    const r = hash(i + 200)
    if (r < 0.2) fillRect(b, x + 2, y0 - 2, 1, 2, s.roof)
    else if (r < 0.32) fillRect(b, x + 1, y0 - 2, 3, 2, s.roof)
    if (s.hasWindows) {
      for (let k = 0; k < 2; k++) {
        const wx = x + 1 + Math.floor(hash(i * 3 + k + 300) * (w - 2))
        const wy = y0 + 2 + Math.floor(hash(i * 3 + k + 400) * 4)
        const isOn = hash(i * 3 + k + 500) < 0.45 || Math.floor(t / 3 + i + k) % 4 === 0
        if (isOn && wy < 9) setPixel(b, wx, wy, WINDOW)
      }
    }
    x += w + 1 + Math.floor(hash(i + 600) * s.gap)
  }
}

// The crane, on an area 96 columns wide or more with the headroom for its
// jib (9 rows): a lattice mast near the right edge, its jib reaching left,
// the trolley creeping along it and back over the loop with its hook
// hanging.
const JIB = -3
function drawCrane(b: PixelBuffer, t: number) {
  const edge = rightOf(b)
  if (edge < 96 || topOf(b) > JIB) return
  const mast = edge - 18
  const jib = JIB
  for (let y = jib; y <= 13; y++) {
    setPixel(b, mast, y, CRANE)
    setPixel(b, mast + 2, y, CRANE)
    setPixel(b, mast + 1, y, wrap(y, 2) === 0 ? CRANE : CRANE_DARK)
  }
  const tip = Math.max(areaOf(b).left + 30, mast - 52)
  fillRect(b, tip, jib, mast - tip + 9, 1, CRANE)
  for (let x = tip + 1; x < mast; x += 2) setPixel(b, x, jib + 1, CRANE_DARK)
  fillRect(b, mast + 6, jib + 1, 3, 2, CRANE_DARK)
  setPixel(b, mast + 1, jib - 1, CRANE)
  const tx = Math.round(lerp(mast - 8, tip + 4, 0.5 - 0.5 * Math.cos((t / LOOP) * Math.PI * 2)))
  setPixel(b, tx, jib + 1, CRANE)
  fillRect(b, tx, jib + 2, 1, 2, CABLE)
  setPixel(b, tx, jib + 4, CRANE)
}

function drawWall(b: PixelBuffer, t: number) {
  const laid = laidAt(t, areaOf(b))
  for (let i = 0; i < laid; i++) {
    const bay = Math.floor(i / 3)
    const course = i % 3
    const y = 12 - course * 2
    const x = WALL_X + bay * BAY + (course === 1 ? 2 : 0)
    // A few bricks a shade darker, for texture.
    const color = hash(i + 900) < 0.3 ? BRICK_SHADE : C.brick
    fillRect(b, x, y, 3, 2, color)
    fillRect(b, x + 3, y, 1, 2, C.mortar)
    if (course === 1 && bay === 0) {
      // The half brick at the middle course's start.
      fillRect(b, WALL_X, y, 1, 2, color)
      fillRect(b, WALL_X + 1, y, 1, 2, C.mortar)
    }
  }
}

export const bricklaying: Scene = {
  id: 'bricklaying',
  loop: LOOP,
  still: 7,
  fadesAtLoop: true,
  focusX: WALL_X + PAST_END + 7,
  // The camera follows Clawd along the wall.
  focus: (t, area) => clawdX(t, area) + 7,
  background: (b, time) => {
    // Long thin clouds in the headroom, drifting slowest of all.
    const off = scrolled(time, LAYERS.clouds.speed)
    for (const p of [14, 70, 115]) {
      eachItem(
        b,
        off,
        150,
        p,
        x => {
          const y = topOf(b) + (p % 2)
          fillRect(b, x + 2, y, 8, 1, CLOUD)
          fillRect(b, x, y + 1, 14, 1, CLOUD)
        },
        16,
      )
    }
  },
  backdrop: (b, t) => {
    drawSkyline(b, t, FAR_SKYLINE)
    drawSkyline(b, t, NEAR_SKYLINE)
    drawCrane(b, t)
  },
  actors: [
    // The wall, behind Clawd: his claw reaches back over its end.
    { kind: 'prop', z: -1, draw: drawWall },
    {
      kind: 'clawd',
      isHero: true,
      at: (t, area) => ({ x: clawdX(t, area), y: CLAWD_TOP }),
      look: (t, area) =>
        isDone(t)
          ? { facing: 0, eyes: 'wide', arms: { left: 'up', right: 'up' } }
          : {
              pose: 'walk',
              // A step every 2 columns he goes, and at least two a second
              // (on a narrow area the wall grows slowly).
              stride: Math.floor(clawdX(t, area) / 2 + t * 2),
              facing: -1,
              isBlinking: blinking(t, 1.5),
              arms: { left: isStriking(t) ? 'out' : 'up', right: 'down' },
            },
    },
    {
      kind: 'prop',
      z: 1,
      draw: (b, t) => {
        if (isDone(t)) return
        // The hammer in Clawd's left claw: raised, or struck out at the
        // wall's end with a spark.
        const tip = clawdAnchors({ arms: { left: isStriking(t) ? 'out' : 'up', right: 'down' } }).left
        const x = clawdX(t, areaOf(b)) + tip.x
        const y = CLAWD_TOP + tip.y
        if (isStriking(t)) {
          fillRect(b, x - 1, y - 1, 1, 3, C.gray)
          setPixel(b, x - 2, y, C.gold)
        } else {
          fillRect(b, x - 1, y - 1, 3, 1, C.gray)
        }
      },
    },
  ],
}

