// Control panel: Clawd flips a switch and the lights come on red, then red
// again, then green, and Clawd cheers. On a wider area more panels stand
// past his, each a bank of small lights blinking slowly over a dial.

import { fillRect, type PixelBuffer, setPixel } from '../pixels'
import { CLAWD_TOP, type Scene } from '../scene'
import { blinking, C, every, still } from './kit'
import { tileOn, WINGS_X } from './wings'

const LOOP = 6
const TRY = 1.6
const LIT_AFTER = 0.5
const RESULTS = [C.red, C.red, C.green]
const LIGHTS = [27, 32, 37]

const attempt = (t: number) => Math.min(RESULTS.length - 1, every(t, TRY))
const isLit = (t: number) => t - attempt(t) * TRY >= LIT_AFTER

// The wings: a panel every PANEL_EVERY columns, lower than Clawd's, with
// four lights, a dial and a slider. Each light steps through a 3 s pattern (on,
// on, off), a second a step, staggered along the bank: 3 s divides the
// loop, so the lights are the same at its end as at its start.
const PANEL_EVERY = 15
const BANK = [C.green, C.gold, C.green, C.red]

function bank(b: PixelBuffer, t: number) {
  tileOn(b, WINGS_X + 2, PANEL_EVERY, (x, p) => {
    fillRect(b, x, 6, 12, 7, C.darkGray)
    fillRect(b, x + 1, 13, 1, 1, C.darkGray)
    fillRect(b, x + 10, 13, 1, 1, C.darkGray)
    BANK.forEach((color, i) => setPixel(b, x + 2 + i * 2, 7, (every(t, 1) + i + p * 2) % 3 === 2 ? C.gray : color))
    fillRect(b, x + 2, 9, 3, 2, C.gray)
    setPixel(b, x + 3 + (p % 2), 9, C.white)
    fillRect(b, x + 6, 10, 4, 1, C.gray)
    setPixel(b, x + 6 + ((p * 3) % 4), 9, C.white)
  })
}

export const controlPanel: Scene = {
  id: 'control-panel',
  loop: LOOP,
  still: 0.9,
  focusX: 26,
  backdrop: (b, t) => {
    fillRect(b, 24, 4, 17, 9, C.darkGray)
    fillRect(b, 25, 13, 1, 1, C.darkGray)
    fillRect(b, 39, 13, 1, 1, C.darkGray)
    bank(b, t)
  },
  actors: [
    {
      kind: 'clawd',
      isHero: true,
      at: still(8, CLAWD_TOP),
      look: t => {
        if (attempt(t) === RESULTS.length - 1 && isLit(t)) return { eyes: 'wide', arms: { left: 'up', right: 'up' } }
        const isFlipping = t < RESULTS.length * TRY && t % TRY < 0.3

        return { isBlinking: blinking(t, 1.3), look: { x: 1, y: 0 }, arms: { left: 'down', right: isFlipping ? 'out' : 'down' } }
      },
    },
  ],
  front: (b, t) => {
    const k = attempt(t)
    for (const x of LIGHTS) fillRect(b, x, 6, 2, 2, isLit(t) ? RESULTS[k]! : C.gray)
    // The switch's slot, and its knob at one end or the other.
    fillRect(b, 31, 10, 4, 1, C.gray)
    fillRect(b, k % 2 === 0 ? 31 : 34, 9, 1, 1, C.white)
  },
}

files.hooks/scenes/crash-test.ts:
// Crash test: a test car, a dummy at the wheel, waits beside Clawd, then
// speeds off across the track, faster and faster, into a small padded
// barrier at the far end: a bump, the pad squashes, sparks and a puff of
// smoke, and the car rolls back a little. The needle of the meter in
// Clawd's claw jumps into the red, and he reads it. The loop fades in the
// next car at the start. Behind, quiet and dim: the test hall's wall with a
// hazard stripe and a marker board every few metres, and the track's
// distance marks on the floor.

import { fillRect, type PixelBuffer, setPixel, topOf } from '../pixels'
import { type Area, areaOf, CLAWD_TOP, drawSprite, type Scene, type Sprite } from '../scene'
import { blinking, C, lerp, reach, still } from './kit'
import { eachItem, fade, wrap } from './layers'

const LOOP = 7
// The run: waiting, then off at GO, faster and faster, into the barrier at
// HIT; the bounce back until SETTLED; Clawd reads the meter from READ.
const GO = 0.6
const HIT = 3.2
const SETTLED = 3.6
const READ = 4
const BOUNCE = 3
const START = 24
const CAR_W = 9
const BARRIER_W = 4
// How far the run goes: up to 140 columns, the barrier 2 short of the edge.
const MAX = 140
const MARGIN = CAR_W + BARRIER_W + 2
const CAR_Y = 10

// The car, nose to the right: a blue body, its window with the yellow
// crash-test dummy, two wheels.
const CAR: Sprite = {
  palette: { b: C.blue, g: C.glass, y: C.gold, d: C.darkGray },
  frames: [['...bbbb..', '..bgyggb.', 'bbbbbbbbb', '.dd...dd.']],
}

// The meter in Clawd's right claw: a grey case with a bar that shoots up
// at the bump, through green and gold into the red, and settles there.
const METER = { x: 16, y: 3 }
const METER_H = 6
const LEVELS = [C.green, C.green, C.gold, C.gold, C.red, C.red]
const RESTING = 1
const READING = 5

// The scenery's shades: faint, well under Clawd's orange.
const WALL_LINE = fade(C.gray, 0.82)
const STRIPE = fade(C.gold, 0.8)
const STRIPE_DARK = fade(C.darkGray, 0.7)
const BOARD = fade(C.gold, 0.74)
const FLOOR = fade(C.gray, 0.8)
const FLOOR_MARK = fade(C.paper, 0.72)

// The car's left column when it hits, and the barrier's.
const hitOf = (area: Area) => START + reach(area, START, MAX, MARGIN)
const barrierOf = (area: Area) => hitOf(area) + CAR_W

function carX(t: number, area: Area): number {
  const hit = hitOf(area)
  if (t < GO) return START
  if (t < HIT) return Math.round(lerp(START, hit, ((t - GO) / (HIT - GO)) ** 2))
  if (t < SETTLED) return Math.round(hit - BOUNCE * Math.sin(((t - HIT) / (SETTLED - HIT)) * (Math.PI / 2)))

  return hit - BOUNCE
}

// The car's speed in columns a second, while it runs.
const speedOf = (t: number, area: Area) => (t >= GO && t < HIT ? (2 * (hitOf(area) - START) * (t - GO)) / (HIT - GO) ** 2 : 0)

// How far up the bar is: resting low, at the bump right to the top, then
// down a step and up again until it settles on the reading.
function levelAt(t: number): number {
  if (t < HIT) return RESTING
  if (t < HIT + 0.3) return METER_H
  if (t < HIT + 0.5) return READING - 1

  return t < HIT + 0.7 ? METER_H : READING
}

function drawMeter(b: PixelBuffer, t: number) {
  const { x, y } = METER
  fillRect(b, x, y, 5, METER_H + 2, C.darkGray)
  fillRect(b, x + 1, y + 1, 3, METER_H, C.ink)
  const level = levelAt(t)
  for (let i = 0; i < level; i++) fillRect(b, x + 1, y + METER_H - i, 3, 1, LEVELS[i]!)
  // A notch at the red line.
  setPixel(b, x + 4, y + METER_H - 3, C.paper)
}

// The barrier: a padded block, red and white, squashed a column for a
// moment at the bump.
function drawBarrier(b: PixelBuffer, t: number) {
  const x = barrierOf(areaOf(b))
  const isSquashed = t >= HIT && t < HIT + 0.2
  const w = isSquashed ? BARRIER_W - 1 : BARRIER_W
  const left = x + BARRIER_W - w
  for (let y = 7; y < 14; y++) fillRect(b, left, y, w, 1, wrap(Math.floor((y - 7) / 2), 2) === 0 ? C.red : C.paper)
  fillRect(b, x + BARRIER_W, 7, 1, 7, C.darkGray)
}

// The test hall: a hazard stripe along the wall, a marker board (a quartered
// target) every 24 columns past the meter, and the floor's distance marks
// every 8.
function drawHall(b: PixelBuffer) {
  const { left, right } = areaOf(b)
  const top = Math.max(topOf(b), 0)
  for (let x = left; x < right; x++) {
    setPixel(b, x, top, WALL_LINE)
    setPixel(b, x, top + 1, wrap(x + top, 4) < 2 ? STRIPE : STRIPE_DARK)
    setPixel(b, x, 13, FLOOR)
    if (wrap(x - START, 8) === 0) setPixel(b, x, 12, FLOOR_MARK)
  }
  eachItem(
    b,
    0,
    24,
    START + 12,
    x => {
      if (x < START) return
      fillRect(b, x, 4, 2, 2, BOARD)
      fillRect(b, x + 2, 6, 2, 2, BOARD)
    },
    4,
  )
}

export const crashTest: Scene = {
  id: 'crash-test',
  loop: LOOP,
  still: 4.6,
  fadesAtLoop: true,
  focusX: 16,
  // The camera, in a raster narrower than the core: on Clawd, along with
  // the car to the barrier, and back to Clawd for the reading.
  focus: (t, area) => {
    const onBarrier = barrierOf(area) - 4
    if (t < GO || t >= READ) return 16
    if (t < HIT) return Math.round(lerp(16, onBarrier, (carX(t, area) - START) / (hitOf(area) - START)))
    if (t < SETTLED) return onBarrier

    return Math.round(lerp(onBarrier, 16, (t - SETTLED) / (READ - SETTLED)))
  },
  backdrop: drawHall,
  actors: [
    {
      kind: 'clawd',
      isHero: true,
      at: still(1, CLAWD_TOP),
      look: t => {
        if (t >= HIT && t < HIT + 0.6) return { eyes: 'wide', look: { x: 1, y: 0 }, arms: { left: 'up', right: 'out' } }
        const isReading = t >= READ

        return { isBlinking: !isReading && blinking(t, 0.9), look: { x: 1, y: isReading ? -1 : 0 }, arms: { left: 'down', right: 'out' } }
      },
    },
    // Speed lines behind the car, longer the faster it goes.
    {
      kind: 'prop',
      z: -1,
      draw: (b, t) => {
        const area = areaOf(b)
        const n = Math.min(12, Math.floor(speedOf(t, area) / 8))
        if (n < 2) return
        const x = carX(t, area)
        fillRect(b, x - n - 1, CAR_Y, n, 1, FLOOR_MARK)
        fillRect(b, x - Math.round(n * 0.6) - 1, CAR_Y + 2, Math.round(n * 0.6), 1, FLOOR_MARK)
      },
    },
    {
      kind: 'prop',
      draw: (b, t) => {
        drawBarrier(b, t)
        const area = areaOf(b)
        drawSprite(b, CAR, 0, carX(t, area), CAR_Y)
        if (t >= HIT && t < HIT + 0.4) {
          // The bump: gold sparks at the nose and a puff of smoke above.
          const x = barrierOf(area) - 1
          for (const [dx, dy] of [[0, -2], [-1, -3], [1, -4], [-2, -1]] as const) setPixel(b, x + dx, CAR_Y + 1 + dy, C.gold)
          if (t >= HIT + 0.1) fillRect(b, x - 2, CAR_Y - 5, 2, 1, C.smoke)
        }
      },
    },
  ],
  front: drawMeter,
}

files.hooks/scenes/dice.ts:
// Dice: Clawd plays a board game. A board of squares runs from beside him
// to near the area's right edge, a goal square with a flag at its end. He
// shakes two big dice and rolls them; they tumble and land in front of the
// board, and the pawn hops along it, a square for each pip. He gathers the
// dice and rolls again, and the second roll takes the pawn onto the goal
// (on a wide area a double six, twice), where he cheers. The loop fades in
// the pawn back at the start. The rolls are made for the board, so the
// pawn always ends on the goal.

import { fillRect, type PixelBuffer } from '../pixels'
import { type Area, areaOf, CLAWD_TOP, drawSprite, type Scene, type Sprite } from '../scene'
import { blinking, C, every, FLAG, lerp, reach, still } from './kit'

const LOOP = 9
// Each roll: shaken until SHAKE_FOR, tumbling until LANDED, the pawn's hops
// from HOPS_AT for HOPS_FOR; the first roll's dice gathered from GATHER.
const ROLLS = [0, 4.2]
const SHAKE_FOR = 0.5
const LANDED = 1.4
const HOPS_AT = 1.6
const HOPS_FOR = 2
const GATHER = 3.6
const GOAL_AT = ROLLS[1]! + HOPS_AT + HOPS_FOR

// The board, on a low table: a square every few columns from BOARD_X, a
// column apart, on rows 7 and 8, the table's edge row 9 and its legs under
// it; the pawn stands on the board, the dice land on the floor in front.
const BOARD_X = 25
const BOARD_Y = 7
const PAWN_Y = 2
// How far the board goes: up to MAX_SQUARES squares (two double sixes),
// up to 150 columns, its flag 2 short of the edge.
const MAX_SQUARES = 24
const MAX = 150
const SQUARES = [C.paper, C.red, C.paper, C.blue, C.paper, C.green]
const PAWN: Sprite = { palette: { p: C.blue }, frames: [['.p.', 'ppp', '.p.', '.p.', 'ppp']] }

// Each die held side by side over Clawd's claw (his right claw's tip is at
// 17, 8), short of the pawn's start, and where it lands, in front of the
// board.
const DICE = [
  { from: { x: 20, y: 3 }, to: { x: 32, y: 9 } },
  { from: { x: 15, y: 3 }, to: { x: 24, y: 9 } },
]
const PIPS: Record<number, string[]> = {
  1: ['...', '.#.', '...'],
  2: ['#..', '...', '..#'],
  3: ['#..', '.#.', '..#'],
  4: ['#.#', '...', '#.#'],
  5: ['#.#', '.#.', '#.#'],
  6: ['#.#', '#.#', '#.#'],
}
const FACES: Sprite = {
  palette: { w: C.white, i: C.ink },
  frames: [1, 2, 3, 4, 5, 6].map(n => ['wwwww', ...PIPS[n]!.map(r => `w${r.replaceAll('#', 'i').replaceAll('.', 'w')}w`), 'wwwww']),
}
// A die mid-tumble, on its corner.
const CORNER: Sprite = { palette: { w: C.white, s: C.paperShade }, frames: [['..w..', '.www.', 'wwsww', '.www.', '..w..']] }

// The board on an area: the squares to the goal (4 to MAX_SQUARES, one
// every 4 columns where it can), spread over its length at a pitch of 4 to
// 6 columns, fractional where it has to be, so the goal lands near the edge.
const boardOf = (area: Area) => reach(area, BOARD_X, MAX, 9)
const squaresOf = (area: Area) => Math.max(4, Math.min(MAX_SQUARES, Math.floor(boardOf(area) / 4)))
const pitchOf = (area: Area) => Math.max(4, Math.min(6, boardOf(area) / squaresOf(area)))
// A square's width, a column short of the narrowest pitch between squares.
const squareW = (area: Area) => Math.floor(pitchOf(area)) - 1
// Square k's left column (k may be fractional, for the pawn mid-hop).
const squareX = (k: number, area: Area) => BOARD_X + Math.round(k * pitchOf(area))

// The two rolls' totals, each 2 to 12, adding up to the squares to the
// goal; and each total as two dice.
function totalsOf(area: Area): [number, number] {
  const n = squaresOf(area)
  const first = Math.max(n - 12, Math.min(12, Math.max(2, Math.round(n * 0.45))))

  return [first, n - first]
}
const diceOf = (total: number): [number, number] => {
  const a = Math.min(6, Math.ceil(total / 2) + (total >= 4 ? 1 : 0))

  return [a, total - a]
}

// Which roll is under way at t (0 or 1), and the time into it.
const rollAt = (t: number) => (t < ROLLS[1]! ? 0 : 1)

// The pawn's square at t: whole squares, and the hop's progress between.
function pawnAt(t: number, area: Area): number {
  const [a, b] = totalsOf(area)
  const hops = (into: number, n: number) => Math.min(n, Math.max(0, ((into - HOPS_AT) / HOPS_FOR) * n))

  return hops(t, a) + (t >= ROLLS[1]! ? hops(t - ROLLS[1]!, b) : 0)
}

function dieAt(i: number, t: number) {
  const d = DICE[i]!
  const roll = rollAt(t)
  const into = t - ROLLS[roll]!
  if (into < SHAKE_FOR) return { x: d.from.x + (every(t, 0.1) % 2), y: d.from.y, isTumbling: false }
  if (into < LANDED) {
    const k = (into - SHAKE_FOR) / (LANDED - SHAKE_FOR)
    const bounce = Math.abs(Math.sin(k * Math.PI * 3)) * 4 * (1 - k)

    return { x: Math.round(lerp(d.from.x, d.to.x, k)), y: Math.round(lerp(d.from.y, d.to.y, k) - bounce), isTumbling: true }
  }
  if (roll === 1 || into < GATHER) return { ...d.to, isTumbling: false }
  // Gathered up in an arc, over his claw.
  const k = (into - GATHER) / (ROLLS[1]! - GATHER)

  return { x: Math.round(lerp(d.to.x, d.from.x, k)), y: Math.round(lerp(d.to.y, d.from.y, k) - 4 * Math.sin(Math.PI * k)), isTumbling: false }
}

// The board, to the goal: coloured squares and plain ones in turn, the goal
// gold with its flag, on the table.
function drawBoard(b: PixelBuffer) {
  const area = areaOf(b)
  const n = squaresOf(area)
  const w = squareW(area)
  const right = squareX(n, area) + w
  fillRect(b, BOARD_X - 1, BOARD_Y + 2, right + 1 - BOARD_X + 1, 1, C.wood)
  for (const x of [BOARD_X, right - 1]) fillRect(b, x, BOARD_Y + 3, 1, 14 - BOARD_Y - 3, C.woodDark)
  for (let k = 0; k <= n; k++) fillRect(b, squareX(k, area), BOARD_Y, w, 2, k === n ? C.gold : SQUARES[k % SQUARES.length]!)
  drawSprite(b, FLAG, 0, squareX(n, area) + w, PAWN_Y)
}

export const dice: Scene = {
  id: 'dice',
  loop: LOOP,
  still: 5.7,
  fadesAtLoop: true,
  focusX: 17,
  backdrop: drawBoard,
  actors: [
    {
      kind: 'clawd',
      isHero: true,
      at: still(2, CLAWD_TOP),
      look: t => {
        if (t >= GOAL_AT && t < GOAL_AT + 0.9) return { eyes: 'wide', look: { x: 1, y: 0 }, arms: { left: 'up', right: 'up' } }
        const into = t - ROLLS[rollAt(t)]!
        const isLanding = into >= LANDED && into < LANDED + 0.5
        if (isLanding) return { eyes: 'wide', look: { x: 1, y: 1 }, arms: { left: 'down', right: 'out' } }
        const isHolding = into < LANDED || (rollAt(t) === 0 && into >= GATHER)

        return { isBlinking: blinking(t, 1.2), look: { x: 1, y: into < LANDED ? 0 : 1 }, arms: { left: 'down', right: isHolding ? 'out' : 'down' } }
      },
    },
    // The pawn, hopping square by square.
    {
      kind: 'prop',
      draw: (b, t) => {
        const area = areaOf(b)
        const at = pawnAt(t, area)
        const hop = at - Math.floor(at)
        // Centred on its square.
        const inset = Math.floor((squareW(area) - 3) / 2)
        drawSprite(b, PAWN, 0, Math.round(squareX(at, area)) + inset, Math.round(PAWN_Y - 2 * Math.sin(Math.PI * hop)))
      },
    },
  ],
  front: (b, t) => {
    const roll = rollAt(t)
    const faces = diceOf(totalsOf(areaOf(b))[roll]!)
    DICE.forEach((_, i) => {
      const at = dieAt(i, t)
      // Tumbling, a die shows a corner, then a face, every 0.12 s.
      const flip = every(t, 0.12) + i
      // Shaken in his claw, it shows a face, then another.
      const isShaken = t - ROLLS[roll]! < SHAKE_FOR
      if (at.isTumbling && flip % 2 === 0) drawSprite(b, CORNER, 0, at.x, at.y)
      else drawSprite(b, FACES, at.isTumbling || isShaken ? flip % 6 : faces[i]! - 1, at.x, at.y)
    })
    if (t >= GOAL_AT && t < GOAL_AT + 0.9 && every(t, 0.15) % 2 === 0) {
      // Sparkles round the flag.
      const x = squareX(squaresOf(areaOf(b)), areaOf(b))
      for (const [dx, dy] of [[-2, 2], [6, 1], [2, 0]] as const) drawSprite(b, { palette: { y: C.gold }, frames: [['.y.', 'yyy', '.y.']] }, 0, x + dx, dy)
    }
  },
}

files.hooks/scenes/dishes.ts:
// Dishes: Clawd washes dishes at a sink; bubbles rise, the dirty stack
// shrinks and the clean one grows. With all five washed, the clean stack
// slides away to the left and five dirty dishes drop onto the empty spot,
// so the loop starts again where it began. On a wider area a drying rack
// of clean plates stands past the sink, then cupboards run on to the edge.

import { fillRect, type PixelBuffer, rightOf, setPixel } from '../pixels'
import { CLAWD_TOP, type Scene } from '../scene'
import { blinking, C, every, still } from './kit'
import { tileOn, WINGS_X } from './wings'

const PER_DISH = 1
const DISHES = 5
const WASHED_AT = PER_DISH * DISHES
// The clean stack slides off, then the dirty dishes drop in, one by one.
const CLEAR_FOR = 0.5
const DROP_EVERY = 0.2
const FALL_FOR = 0.15
const LOOP = WASHED_AT + CLEAR_FOR + DROP_EVERY * DISHES
const DIRTY_X = 38

function dish(b: PixelBuffer, x: number, y: number, i: number, isDirty: boolean) {
  fillRect(b, x, y, 5, 1, isDirty ? C.paperShade : C.white)
  if (isDirty) setPixel(b, x + 1 + (i % 3), y, C.darkGray)
}

function stack(b: PixelBuffer, x: number, count: number, isDirty: boolean) {
  for (let i = 0; i < count; i++) dish(b, x, 12 - i, i, isDirty)
}

// The wings: a wire rack with plates standing in it on edge, then a row
// of floor cupboards under one counter, each with two doors and their
// knobs.
const RACK_X = WINGS_X + 2
const CUPBOARDS_X = RACK_X + 13
const CUPBOARD_W = 9

function kitchen(b: PixelBuffer) {
  fillRect(b, RACK_X, 13, 10, 1, C.gray)
  fillRect(b, RACK_X, 10, 1, 3, C.gray)
  fillRect(b, RACK_X + 9, 10, 1, 3, C.gray)
  for (let i = 0; i < 4; i++) fillRect(b, RACK_X + 2 + i * 2, 8, 1, 5, C.white)
  if (CUPBOARDS_X < rightOf(b)) fillRect(b, CUPBOARDS_X, 7, rightOf(b) - CUPBOARDS_X, 1, C.gray)
  tileOn(b, CUPBOARDS_X, CUPBOARD_W, x => {
    fillRect(b, x, 8, CUPBOARD_W, 6, C.wood)
    fillRect(b, x, 8, 1, 6, C.woodDark)
    fillRect(b, x + 4, 8, 1, 5, C.woodDark)
    fillRect(b, x, 13, CUPBOARD_W, 1, C.woodDark)
    setPixel(b, x + 3, 10, C.gold)
    setPixel(b, x + 5, 10, C.gold)
  })
}

const isRestocking = (t: number) => t >= WASHED_AT

export const dishes: Scene = {
  id: 'dishes',
  loop: LOOP,
  still: 2.3,
  focusX: 26,
  backdrop: b => {
    fillRect(b, 22, 9, 14, 5, C.gray)
    fillRect(b, 23, 10, 12, 2, C.glass)
    kitchen(b)
  },
  actors: [
    {
      kind: 'clawd',
      isHero: true,
      at: still(7, CLAWD_TOP),
      look: t =>
        isRestocking(t)
          ? { isBlinking: blinking(t, 0.3), look: { x: 1, y: 0 }, arms: { left: 'down', right: 'down' } }
          : { isBlinking: blinking(t, 0.3), look: { x: 1, y: 1 }, arms: { left: 'down', right: every(t, 0.2) % 2 === 0 ? 'out' : 'down' } },
    },
  ],
  front: (b, t) => {
    if (isRestocking(t)) {
      const since = t - WASHED_AT
      stack(b, 1 - Math.round(Math.min(1, since / CLEAR_FOR) * 6), DISHES, false)
      // Each dirty dish falls from the top to its place on the stack.
      for (let i = 0; i < DISHES; i++) {
        const k = (since - CLEAR_FOR - i * DROP_EVERY) / FALL_FOR
        if (k >= 0) dish(b, DIRTY_X, Math.round(Math.min(1, k) * (12 - i)), i, true)
      }
    } else {
      const washed = every(t, PER_DISH)
      stack(b, DIRTY_X, DISHES - washed, true)
      stack(b, 1, washed, false)
    }
    for (let k = 0; k < 4; k++) {
      const rise = (t * 0.8 + k * 0.25) % 1
      setPixel(b, 25 + k * 3, 9 - Math.floor(rise * 6), C.white)
    }
  },
}

