// Fishing: Clawd fishes from the end of a jetty. Up comes an old boot, and
// on the next bite a fish. On a wider area the water runs to the edge, and
// now and then a fish jumps out of it with a splash.

import { fillRect, type PixelBuffer, rightOf, setPixel } from '../pixels'
import { drawSprite, type Scene, type Sprite } from '../scene'
import { blinking, C, every, lerp, still, wave } from './kit'
import { tileOn } from './wings'

const LOOP = 8
const LINE_X = 30
const WATER = 11
const REEL_FOR = 0.8
const HOLD_FOR = 1
const BOOT: Sprite = { palette: { d: C.darkGray }, frames: [['dd.', 'dd.', 'ddd']] }
const FISH: Sprite = { palette: { g: C.green, y: C.gold }, frames: [['.ggg.g', 'gyggg.', '.ggg.g']] }
const CATCHES = [
  { from: 2.4, sprite: BOOT, x: LINE_X - 1 },
  { from: 6, sprite: FISH, x: LINE_X - 3 },
]

// On a wider area, fish jump in the wings: one every JUMP_EVERY columns
// from column 52, each at its own moment of the loop (JUMP_AT, in turn),
// leaping out of the water in an arc JUMP_W columns long and JUMP_H rows
// high over JUMP_FOR seconds, with a splash where it leaves the water and
// where it falls back in.
const JUMP_EVERY = 29
const JUMP_AT = [1.2, 5.1, 3.4, 7.3, 0.4, 4.6, 2.5, 6.2]
const JUMP_FOR = 1
const JUMP_W = 11
const JUMP_H = 5
const SPLASH_FOR = 0.3
// Facing right, rising, level at the top, and falling: its head tips up, then down.
const JUMPER: Sprite = { palette: { g: C.green }, frames: [['....g', 'g.ggg', '.gg..'], ['g.gg.', '.gggg', 'g.gg.'], ['.gg..', 'g.ggg', '....g']] }

function drawJumps(b: PixelBuffer, t: number) {
  tileOn(b, 52, JUMP_EVERY, (x, k) => {
    const age = (((t - JUMP_AT[k % JUMP_AT.length]!) % LOOP) + LOOP) % LOOP
    if (age < JUMP_FOR) {
      const p = age / JUMP_FOR
      const y = WATER - 3 - Math.round(JUMP_H * Math.sin(Math.PI * p))
      drawSprite(b, JUMPER, p < 0.35 ? 0 : p < 0.65 ? 1 : 2, x + Math.round(p * (JUMP_W - 5)), y)
    }
    // The splash: out at the start, back in at the end.
    if (age < SPLASH_FOR) splash(b, x + 1)
    else if (age >= JUMP_FOR - 0.1 && age < JUMP_FOR + SPLASH_FOR) splash(b, x + JUMP_W - 4)
  })
}

// Drops thrown up over the water, either side of a column.
function splash(b: PixelBuffer, x: number) {
  setPixel(b, x - 1, WATER - 1, C.glass)
  setPixel(b, x + 2, WATER - 1, C.glass)
  setPixel(b, x - 2, WATER - 2, C.white)
  setPixel(b, x + 3, WATER - 2, C.white)
}

// The catch on the line at a moment, and its top row, if any.
function caught(t: number) {
  for (const c of CATCHES) {
    const age = t - c.from
    if (age >= 0 && age < REEL_FOR + HOLD_FOR) return { ...c, y: Math.round(lerp(WATER, 3, age / REEL_FOR)) }
  }

  return null
}

export const fishing: Scene = {
  id: 'fishing',
  loop: LOOP,
  still: 6,
  focusX: 24,
  backdrop: (b, t) => {
    fillRect(b, 0, 9, 21, 1, C.wood)
    fillRect(b, 3, 10, 1, 4, C.woodDark)
    fillRect(b, 17, 10, 1, 4, C.woodDark)
    fillRect(b, 21, WATER, rightOf(b) - 21, 3, C.blue)
    // 25 steps a loop over the 25 columns of water: the ripples come back
    // to where they started as the loop wraps. On a wider area the water
    // runs to the edge and its ripples repeat every 25 columns; the next
    // tile starts at column 47, which is drawn only past the bare stage.
    const tiles = rightOf(b) > 48 ? Math.ceil((rightOf(b) - 22) / 25) : 1
    for (let tile = 0; tile < tiles; tile++) {
      for (let k = 0; k < 3; k++) setPixel(b, 22 + 25 * tile + ((k * 9 + every(t, LOOP / 25)) % 25), WATER, C.glass)
    }
    drawJumps(b, t)
  },
  actors: [
    {
      kind: 'clawd',
      isHero: true,
      // Sitting at y 1, Clawd's body rests on the jetty (row 9).
      at: still(6, 1),
      look: t => {
        const c = caught(t)
        const isHeld = c !== null && t - c.from >= REEL_FOR

        return { pose: 'sit', eyes: isHeld && c.sprite === FISH ? 'wide' : 'open', isBlinking: !isHeld && blinking(t, 1.4), look: { x: 1, y: isHeld ? 0 : 1 }, arms: { left: 'down', right: 'out' } }
      },
    },
  ],
  front: (b, t) => {
    // The rod, from the claw's tip (21, 5) up to (LINE_X, 1).
    for (let i = 0; i <= 9; i++) setPixel(b, 21 + i, 5 - Math.round((i * 4) / 9), C.wood)
    const c = caught(t)
    const end = c ? c.y - 1 : WATER - 1
    for (let y = 2; y <= end; y++) setPixel(b, LINE_X, y, C.gray)
    if (c) drawSprite(b, c.sprite, 0, c.x, c.y)
    else setPixel(b, LINE_X, WATER - (wave(t, 1.2) > 0.5 ? 1 : 0), C.red)
  },
}

files.hooks/scenes/flashlight.ts:
// Flashlight: a dark storeroom runs the area's width, far shelves of books
// and jars along the back wall, nearer crates and barrels on the floor.
// Clawd's torch throws a pool of light that shows them in their colours,
// its cone half lit; the unlit room is the terminal's own background, the
// crates faint shapes in it. The pool sweeps out towards the far edge and
// back, and ends on the bug: it lights up red, Clawd's eyes widen and a
// "!" appears.

import { fillRect, type PixelBuffer, rightOf, setPixel } from '../pixels'
import { type Area, areaOf, CLAWD_TOP, drawSprite, type Scene, type Sprite } from '../scene'
import { blinking, BOX, C, lerp, reach, still, hash as seededHash } from './kit'
import { drawLit } from './layers'

const LOOP = 8
const LENS = { x: 20, y: 8 }
// The sweep: out towards the far edge, back past the bug, onto it, held.
const OUT = 3.4
const BACK = 5.6
const SPOT = { rx: 7, ry: 5.5 }
const START = { x: 30, y: 4 }
const BUG_Y = 12
// The shelves' uprights stand every BAY columns from SHELVES_X; the bug
// sits mid-bay.
const SHELVES_X = 22
const BAY = 26

// How far out the pool goes: up to 150 columns past its start, 9 short of
// the edge.
const farOf = (area: Area) => START.x + reach(area, START.x, 150, 9)
// The bug's left column: mid-bay, about 60% across (on the core alone,
// at 38), never past the pool's reach.
function bugX(area: Area): number {
  if (area.right <= 48) return 38
  const target = Math.min(area.right * 0.62, farOf(area) - 4)

  return SHELVES_X + 11 + BAY * Math.max(0, Math.round((target - 35) / BAY))
}

const ease = (k: number) => 0.5 - 0.5 * Math.cos(Math.PI * Math.max(0, Math.min(1, k)))
// The pool's sway: from row 0 (3 rows under the area's top on 7 and 8 rows,
// so it stays round there) down to row 8.
const swayY = (t: number, area: Area) => lerp(Math.max(0, area.top + 3), 8, (1 + Math.sin(t * 2.1)) / 2)
// Where the pool of light is at t.
function aimAt(t: number, area: Area): { x: number; y: number } {
  const far = farOf(area)
  const onBug = { x: bugX(area) + 2, y: BUG_Y - 1 }
  if (t < OUT) return { x: lerp(START.x, far, ease(t / OUT)), y: swayY(t, area) }
  if (t < BACK) {
    // Back past the bug, a little high, then onto it.
    const k = ease((t - OUT) / (BACK - OUT))

    return { x: lerp(far, onBug.x, k), y: lerp(swayY(OUT, area), onBug.y, k) - Math.sin(k * Math.PI) * 3 }
  }

  return onBug
}

// How lit a pixel is: 1 in the pool's middle, 0.7 at its rim, 0.3 in the
// cone from the lens, 0 in the dark.
function lightAt(x: number, y: number, aim: { x: number; y: number }): number {
  const d = ((x - aim.x) / SPOT.rx) ** 2 + ((y - aim.y) / SPOT.ry) ** 2
  if (d <= 0.4) return 1
  if (d <= 1) return 0.7
  if (x <= LENS.x || x >= aim.x) return 0
  const k = (x - LENS.x) / (aim.x - LENS.x)
  const middle = lerp(LENS.y, aim.y, k)
  const half = lerp(0.5, SPOT.ry * 0.55, k)

  return Math.abs(y - middle) <= half ? 0.3 : 0
}

const BOOKS = [C.red, C.blue, C.green, C.gold, C.paperShade, C.violet]
const hash = (n: number) => seededHash(n, 11)

// The far layer: two shelves along the back wall from SHELVES_X to the
// edge, books, jars and the odd box along them, with gaps; the uprights.
function drawShelves(b: PixelBuffer) {
  for (const plank of [0, 6]) {
    fillRect(b, SHELVES_X, plank, rightOf(b) - SHELVES_X, 1, C.wood)
    let x = SHELVES_X + 2
    for (let i = plank * 100; x < rightOf(b); i++) {
      const r = hash(i)
      if (r < 0.55) {
        const h = 2 + Math.floor(hash(i + 7) * 3)
        fillRect(b, x, plank - h, 1, h, BOOKS[Math.floor(hash(i + 3) * BOOKS.length)]!)
        x += 1
      } else if (r < 0.68) {
        fillRect(b, x, plank - 3, 2, 3, C.glass)
        setPixel(b, x, plank - 1, C.liquid)
        setPixel(b, x + 1, plank - 1, C.liquid)
        x += 3
      } else if (r < 0.78) {
        fillRect(b, x, plank - 3, 4, 3, C.paperShade)
        x += 5
      } else x += 2 + Math.floor(hash(i + 5) * 4)
    }
  }
  for (let x = SHELVES_X; x < rightOf(b); x += BAY) fillRect(b, x, -4, 1, 18, C.woodDark)
}

const BARREL: Sprite = { palette: { w: C.wood, d: C.woodDark, g: C.gray }, frames: [['.ddd.', 'wwwww', 'ggggg', 'wwwww', 'wwwww', 'ggggg', '.ddd.']] }
const SMALL_BOX: Sprite = { palette: { b: C.wood, d: C.woodDark }, frames: [['ddddd', 'dbbbd', 'dbbbd', 'ddddd']] }

// The near layer: crates, boxes and barrels on the floor, the floor kept
// clear round the bug.
function drawCrates(b: PixelBuffer) {
  const bx = bugX(areaOf(b))
  for (let x = 26, i = 0; x < rightOf(b); i++) {
    const r = hash(i + 500)
    if (x + 10 > bx - 8 && x < bx + 12) {
      x = bx + 12
      continue
    }
    if (r < 0.4) {
      drawSprite(b, BOX, 0, x, 7)
      if (hash(i + 600) < 0.4) drawSprite(b, SMALL_BOX, 0, x + 2, 3)
      x += 10 + Math.floor(hash(i + 700) * 8)
    } else if (r < 0.65) {
      drawSprite(b, BARREL, 0, x, 7)
      x += 7 + Math.floor(hash(i + 700) * 8)
    } else {
      drawSprite(b, SMALL_BOX, 0, x, 10)
      drawSprite(b, SMALL_BOX, 0, x + 5, 10)
      x += 12 + Math.floor(hash(i + 700) * 8)
    }
  }
}

const BUG: Sprite = { palette: { r: C.red, d: C.ink, l: C.darkGray }, frames: [['.rr.', 'drrd', 'l..l'], ['.rr.', 'drrd', '.ll.']] }

export const flashlight: Scene = {
  id: 'flashlight',
  loop: LOOP,
  still: 6.5,
  fadesAtLoop: true,
  // A narrow raster keeps Clawd and his torch in view.
  focusX: 19,
  backdrop: (b, t) => {
    const area = areaOf(b)
    const aim = aimAt(t, area)
    const light = (x: number, y: number) => lightAt(x, y, aim)
    // The back wall shows only in the light; the shelves are nearly gone in
    // the dark, the crates faint shapes, the bug a dim one.
    drawLit(b, drawShelves, light, { dark: 1, bare: C.beam })
    drawLit(b, drawCrates, light, { dark: 0.84 })
    drawLit(b, layer => drawSprite(layer, BUG, Math.floor(t * 6), bugX(area), BUG_Y - 1), light, { dark: 0.92 })
  },
  actors: [
    {
      kind: 'clawd',
      isHero: true,
      at: still(4, CLAWD_TOP),
      look: (t, area) => {
        const isFound = t >= BACK
        const aim = aimAt(t, area)

        return {
          eyes: isFound ? 'wide' : 'open',
          isBlinking: !isFound && blinking(t, 0.6),
          look: { x: 1, y: aim.y > 9 ? 1 : aim.y < 2 ? -1 : 0 },
          arms: { left: 'down', right: 'out' },
        }
      },
    },
  ],
  front: (b, t) => {
    // The torch in the right claw: its body, then the lens.
    setPixel(b, LENS.x - 1, LENS.y, C.gray)
    setPixel(b, LENS.x, LENS.y, C.white)
    // Found: a red "!" over the bug.
    if (t >= BACK + 0.2) {
      const x = bugX(areaOf(b)) + 1
      fillRect(b, x, BUG_Y - 9, 1, 3, C.red)
      setPixel(b, x, BUG_Y - 5, C.red)
    }
  },
}

