// Red pen: Clawd reads a page, circles each mistake in red, and each circle
// turns into a green tick once the mistake is fixed. On a wider area,
// pages read already are pinned up in the wings, some marked in red.

import { fillRect, setPixel } from '../pixels'
import { CLAWD_TOP, type Scene } from '../scene'
import { blinking, C, every, still } from './kit'
import { tileOn } from './wings'

const LOOP = 6
const PER_MISTAKE = 1.5
const CIRCLED_FOR = 0.9
const MISTAKES = [
  { x: 31, y: 4 },
  { x: 28, y: 7 },
  { x: 33, y: 10 },
]
const RING: [number, number][] = [[-1, -1], [0, -1], [1, -1], [-2, 0], [2, 0], [-1, 1], [0, 1], [1, 1]]
const TICKED: [number, number][] = [[-1, 0], [0, 1], [1, 0], [2, -1]]
// The pinned pages: 6 x 7, one every PINNED_EVERY columns, every other one
// a row lower; each third, from the second, has a line struck in red.
const PINNED_EVERY = 12

export const redPen: Scene = {
  id: 'red-pen',
  loop: LOOP,
  still: 2.1,
  focusX: 26,
  backdrop: b => {
    fillRect(b, 24, 2, 13, 11, C.paper)
    for (const y of [4, 7, 10]) fillRect(b, 26, y, 9, 1, C.paperShade)
    tileOn(b, 50, PINNED_EVERY, (x, k) => {
      const y = 4 + (k % 2)
      fillRect(b, x, y, 6, 7, C.paper)
      for (const dy of [2, 4]) fillRect(b, x + 1, y + dy, 4, 1, C.paperShade)
      if (k % 3 === 1) fillRect(b, x + 1, y + 4, 4, 1, C.red)
      setPixel(b, x + 2, y, C.darkGray)
    })
  },
  actors: [
    {
      kind: 'clawd',
      isHero: true,
      at: still(8, CLAWD_TOP),
      look: t => ({
        isBlinking: blinking(t, 0.2),
        look: { x: 1, y: every(t, PER_MISTAKE) % 2 === 0 ? -1 : 1 },
        arms: { left: 'down', right: t < MISTAKES.length * PER_MISTAKE && t % PER_MISTAKE < CIRCLED_FOR ? 'out' : 'down' },
      }),
    },
  ],
  front: (b, t) => {
    MISTAKES.forEach((m, i) => {
      const age = t - i * PER_MISTAKE
      if (age < 0 || age < CIRCLED_FOR) setPixel(b, m.x, m.y, C.ink)
      if (age < 0) return
      const isCircled = age < CIRCLED_FOR
      for (const [dx, dy] of isCircled ? RING : TICKED) setPixel(b, m.x + dx, m.y + dy, isCircled ? C.red : C.green)
    })
  },
}

files.hooks/scenes/road-trip.ts:
// Road trip: Clawd walks, nearly in place, while the world goes by in
// layers, right to left, each slower the further off it is: clouds in the
// headroom, a far range of slate mountains with snow on the tallest, pine
// hills, and nearest a fence with flags by a dashed road. A crescent moon
// stands still over it all. Every layer is behind Clawd, each fainter with
// distance, and each repeats at its own period, so they never line up.

import { fillRect, type PixelBuffer, rightOf, setPixel, topOf } from '../pixels'
import { CLAWD_TOP, type Scene } from '../scene'
import { blinking, C } from './kit'
import { eachColumn, eachItem, fade, type LayerSpec, scrolled, wrap } from './layers'

// Each layer's speed (columns a second) and how far it fades.
export const LAYERS = {
  clouds: { speed: 0.4, fade: 0.78 },
  mountains: { speed: 1, fade: 0.72 },
  hills: { speed: 2.5, fade: 0.66 },
  near: { speed: 6, fade: 0.3 },
} as const satisfies Record<string, LayerSpec>

const CLOUD = fade(C.sky, LAYERS.clouds.fade)
const MOUNTAIN = fade(C.skyShade, LAYERS.mountains.fade)
const MOUNTAIN_LIT = fade(C.skyShade, 0.58)
const SNOW = fade(C.paperShade, 0.55)
const MOON = fade(C.paper, 0.45)
const HILL = fade(C.green, 0.78)
const HILL_EDGE = fade(C.green, LAYERS.hills.fade)
const TREE = fade(C.green, 0.55)
const TREE_DARK = fade(C.green, 0.68)
const TRUNK = fade(C.woodDark, 0.35)
const ROAD = fade(C.road, LAYERS.near.fade)
const ROAD_GAP = fade(C.road, 0.6)
const RAIL = fade(C.wood, 0.45)
const POST = fade(C.woodDark, LAYERS.near.fade)
const POLE = POST
const PENNANTS = [fade(C.red, LAYERS.near.fade), fade(C.blue, LAYERS.near.fade)] as const

// The far range: peaks (column in the pattern, top row), each slope a row a
// column; the pattern repeats every FAR_P columns.
const FAR_P = 150
const PEAKS = [
  { x: 8, y: 3 },
  { x: 27, y: 0 },
  { x: 44, y: 2 },
  { x: 63, y: 1 },
  { x: 84, y: 4 },
  { x: 101, y: -1 },
  { x: 118, y: 2 },
  { x: 134, y: 1 },
]
function mountainTop(u: number): { y: number; peak: number; isLit: boolean } {
  let best = { y: 99, peak: 99, isLit: true }
  for (const p of PEAKS) {
    const right = wrap(u - p.x, FAR_P)
    const left = wrap(p.x - u, FAR_P)
    const y = p.y + Math.min(left, right)
    if (y < best.y) best = { y, peak: p.y, isLit: left <= right }
  }

  return best
}

// The hills: a rolling line repeating every MID_P columns, pines along it.
const MID_P = 128
const hillTop = (u: number) =>
  Math.round(8.2 + 1.4 * Math.sin((u / MID_P) * Math.PI * 4) + 0.9 * Math.sin((u / MID_P) * Math.PI * 6 + 1.3))
const PINES = [6, 11, 30, 52, 57, 61, 88, 103, 109]

// The near layer: a fence post every 8 columns, a flag every 48.
const NEAR_P = 96
const FLAGS = [20, 68]
const CLOUDS_P = 130
const CLOUDS = [10, 58, 95]

const PINE_TALL = ['.t.', '.t.', 'ttt', '.t.', 'ttt', 'ddd', '.k.']
const PINE_SHORT = ['.t.', 'ttt', '.t.', 'ttt', '.k.']
function drawPine(b: PixelBuffer, x: number, base: number, isTall: boolean) {
  const rows = isTall ? PINE_TALL : PINE_SHORT
  rows.forEach((row, dy) => {
    for (let dx = 0; dx < 3; dx++) {
      const ch = row[dx]
      const color = ch === 't' ? TREE : ch === 'd' ? TREE_DARK : ch === 'k' ? TRUNK : null
      if (color !== null) setPixel(b, x + dx, base - rows.length + 1 + dy, color)
    }
  })
}

const MOON_ROWS = ['.mmm.', 'mm..m', 'mm...', 'mm..m', '.mmm.']

function drawWorld(b: PixelBuffer, time: number) {
  const top = topOf(b)
  // Clouds in the headroom (on 7 rows, the sky's top), drifting slowest.
  const cloudOff = scrolled(time, LAYERS.clouds.speed)
  for (const p of CLOUDS) {
    eachItem(b, cloudOff, CLOUDS_P, p, x => {
      const y = top + (p % 3)
      fillRect(b, x + 1, y, 6, 1, CLOUD)
      fillRect(b, x, y + 1, 9, 1, CLOUD)
    })
  }
  // The moon, farthest of all, never moves; the mountains rise in front of it.
  const mx = Math.max(30, rightOf(b) - 12)
  MOON_ROWS.forEach((row, dy) => {
    for (let dx = 0; dx < 5; dx++) if (row[dx] === 'm') setPixel(b, mx + dx, top + dy, MOON)
  })
  // The far range, snow on the tallest peaks, ragged on the shaded side.
  eachColumn(b, scrolled(time, LAYERS.mountains.speed), FAR_P, (x, u) => {
    const { y: peakTop, peak, isLit } = mountainTop(u)
    for (let y = peakTop; y <= 11; y++) setPixel(b, x, y, isLit ? MOUNTAIN_LIT : MOUNTAIN)
    if (peak <= 1) for (let y = peakTop; y < peak + (isLit ? 3 : 2); y++) setPixel(b, x, y, SNOW)
  })
  // The hills, then their pines.
  const midOff = scrolled(time, LAYERS.hills.speed)
  eachColumn(b, midOff, MID_P, (x, u) => {
    const hill = hillTop(u)
    setPixel(b, x, hill, HILL_EDGE)
    for (let y = hill + 1; y <= 12; y++) setPixel(b, x, y, HILL)
  })
  PINES.forEach((p, i) => eachItem(b, midOff, MID_P, p, x => drawPine(b, x - 1, hillTop(p), i % 3 !== 1)))
  // The near layer: the dashed road, the fence's rail and posts, the flags.
  const nearOff = scrolled(time, LAYERS.near.speed)
  eachColumn(b, nearOff, NEAR_P, (x, u) => {
    setPixel(b, x, 13, wrap(u, 6) < 3 ? ROAD : ROAD_GAP)
    setPixel(b, x, 10, RAIL)
  })
  for (let p = 0; p < NEAR_P; p += 8) eachItem(b, nearOff, NEAR_P, p, x => fillRect(b, x, 9, 1, 4, POST))
  FLAGS.forEach((p, i) =>
    eachItem(b, nearOff, NEAR_P, p, x => {
      fillRect(b, x, 4, 1, 9, POLE)
      // The pennant flaps: long, then short.
      const isLong = Math.floor(time * 4 + i) % 2 === 0
      fillRect(b, x + 1, 4, isLong ? 3 : 2, 1, PENNANTS[i]!)
      fillRect(b, x + 1, 5, isLong ? 2 : 3, 1, PENNANTS[i]!)
    }),
  )
}

// Clawd strolls a little forward and back on the spot, his stride keeping
// pace with the road.
const LOOP = 4
const clawdX = (t: number) => 9 + Math.round(Math.sin((t / LOOP) * Math.PI * 2) * 1.5)

export const roadTrip: Scene = {
  id: 'road-trip',
  loop: LOOP,
  still: 3,
  focusX: 18,
  background: drawWorld,
  actors: [
    {
      kind: 'clawd',
      isHero: true,
      at: t => ({ x: clawdX(t), y: CLAWD_TOP }),
      look: t => ({
        pose: 'walk',
        stride: Math.floor(t * 8),
        facing: 1,
        isBlinking: blinking(t, 0.4),
        arms: { left: 'down', right: 'down' },
      }),
    },
  ],
}

files.hooks/scenes/rocket.ts:
// Rocket: one of Done's scenes. A small rocket on a pad beside Clawd
// fizzes, lifts off in a cloud of smoke and arcs over the drifting stars,
// turning from upright to sideways, a gold trail fading behind it, and
// pops in a burst of sixteen sparks; Clawd follows it with his eyes and
// cheers at the pop. On a wider area it flies further, up to 150 columns,
// so it is never too quick to follow. The loop fades in the next rocket on
// the pad.

import { fillRect, type PixelBuffer, setPixel } from '../pixels'
import { type Area, areaOf, CLAWD_TOP, drawSprite, type Scene, type Sprite } from '../scene'
import { blinking, C, drawStarfield, every, reach, still } from './kit'

const LOOP = 8
const FIZZ = 0.8
const LIFT = 1.6
const POP = 4.8
const BURST = 1.6
const JUMP = 0.4
const PAD_X = 24

// The flight: a curve from the pad, up past a point over it, to where it
// pops, 8 columns short of the edge at most 150 columns on, high in the
// sky (the headroom's top rows too, on a taller area).
const P0 = { x: PAD_X + 1, y: 7.5 }
const p1Of = (area: Area) => ({ x: PAD_X + 6, y: area.top - 2 })
export const popOf = (area: Area) => ({ x: P0.x + reach(area, P0.x, 150, 8), y: area.top + 5 })
const sOf = (t: number) => Math.max(0, Math.min(1, (t - LIFT) / (POP - LIFT))) ** 1.5
function pointAt(s: number, area: Area) {
  const p1 = p1Of(area)
  const p2 = popOf(area)
  const u = 1 - s

  return { x: u * u * P0.x + 2 * u * s * p1.x + s * s * p2.x, y: u * u * P0.y + 2 * u * s * p1.y + s * s * p2.y }
}
function headingAt(s: number, area: Area) {
  const p1 = p1Of(area)
  const p2 = popOf(area)

  return { x: 2 * (1 - s) * (p1.x - P0.x) + 2 * s * (p2.x - p1.x), y: 2 * (1 - s) * (p1.y - P0.y) + 2 * s * (p2.y - p1.y) }
}

// The rocket at three headings: up, up and right, right. Each with its
// centre (cx, cy) and where its flame comes out.
type Ship = { sprite: Sprite; cx: number; cy: number; flame: { x: number; y: number; dx: number; dy: number } }
const PAL = { r: C.red, w: C.paper, b: C.blue }
const SHIPS: Ship[] = [
  { sprite: { palette: PAL, frames: [['.r.', 'www', 'wbw', 'www', 'rwr', 'r.r']] }, cx: 1, cy: 2.5, flame: { x: 1, y: 6, dx: 0, dy: 1 } },
  { sprite: { palette: PAL, frames: [['....rr', '...wwr', '..wbw.', 'rwww..', '.ww...', '..r...']] }, cx: 2.5, cy: 2.5, flame: { x: 0, y: 5, dx: -1, dy: 1 } },
  { sprite: { palette: PAL, frames: [['rrwww.', '.wwbwr', 'rrwww.']] }, cx: 2.5, cy: 1, flame: { x: -1, y: 1, dx: -1, dy: 0 } },
]
function shipFor(s: number, area: Area): Ship {
  const h = headingAt(s, area)
  const angle = Math.atan2(-h.y, h.x) * (180 / Math.PI)

  return angle > 62 ? SHIPS[0]! : angle > 24 ? SHIPS[1]! : SHIPS[2]!
}

function drawShip(b: PixelBuffer, x: number, y: number, ship: Ship, t: number, isLit: boolean) {
  const left = Math.round(x - ship.cx)
  const top = Math.round(y - ship.cy)
  drawSprite(b, ship.sprite, 0, left, top)
  if (!isLit) return
  const { flame } = ship
  const flicker = every(t, 0.08) % 2 === 0
  setPixel(b, left + flame.x, top + flame.y, flicker ? C.gold : C.white)
  setPixel(b, left + flame.x + flame.dx, top + flame.y + flame.dy, flicker ? C.orange : C.gold)
}

// Sparkles left along the path: bright near the rocket, dimmer and fewer
// further back, twinkling; after the pop they go out from the back.
const TRAIL = 16
function drawTrail(b: PixelBuffer, t: number, area: Area) {
  const s = sOf(t)
  const gone = t > POP ? Math.floor(((t - POP) / 1.2) * TRAIL) : 0
  for (let j = 2; j <= TRAIL - gone; j++) {
    const back = s - j * 0.035
    if (back <= 0.02) break
    const p = pointAt(back, area)
    const twinkle = (every(t, 0.1) + j) % 3
    if (j > 5 && twinkle === 0) continue
    const color = j <= 3 ? C.gold : j <= 7 ? (twinkle === 1 ? C.white : C.gold) : j <= 11 ? C.smoke : C.darkGray
    setPixel(b, p.x + (j % 2 === 0 ? 0 : 1) * (j > 7 ? 1 : 0), p.y, color)
  }
}

// The pop: a white flash, then sixteen sparks in four colours flying out,
// falling a little and twinkling out.
const RAYS = Array.from({ length: 16 }, (_, k) => ({ x: Math.cos((k * Math.PI) / 8), y: Math.sin((k * Math.PI) / 8) }))
const SPARKS = [C.gold, C.blue, C.green, C.red]
function drawPop(b: PixelBuffer, t: number, area: Area) {
  const k = t - POP
  if (k < 0 || k >= BURST) return
  const at = popOf(area)
  if (k < 0.12) {
    fillRect(b, at.x - 1, at.y - 1, 3, 3, C.white)

    return
  }
  const radius = Math.min(6, 1 + k * 12)
  const fall = Math.floor(k * k * 2.5)
  const isFading = k > BURST * 0.55
  RAYS.forEach((ray, i) => {
    const r = i % 2 === 0 ? radius : radius * 0.65
    if (isFading && (every(t, 0.1) + i) % 2 === 0) return
    const x = at.x + Math.round(ray.x * r)
    const y = at.y + Math.round(ray.y * r * 0.85) + fall
    setPixel(b, x, y, SPARKS[i % 4]!)
    if (!isFading && r > 2) setPixel(b, at.x + Math.round(ray.x * (r - 1)), at.y + Math.round(ray.y * (r - 1) * 0.85) + fall, C.white)
  })
}

// The pad: a plate on two legs; at lift-off smoke billows out either side,
// spreading and thinning.
function drawPad(b: PixelBuffer, t: number) {
  fillRect(b, PAD_X - 2, 11, 7, 1, C.gray)
  fillRect(b, PAD_X - 1, 12, 1, 2, C.darkGray)
  fillRect(b, PAD_X + 3, 12, 1, 2, C.darkGray)
  const k = t - (LIFT - 0.3)
  if (k > 0 && k < 1.6) {
    const spread = Math.floor(k * 6)
    for (const side of [-1, 1]) {
      for (let i = 0; i < 3; i++) {
        if ((every(t, 0.12) + i) % 4 === 0 && k > 0.8) continue
        const x = PAD_X + 1 + side * (3 + spread + i * 2)
        setPixel(b, x, 12 - (i % 2), k > 1 ? C.darkGray : C.smoke)
        setPixel(b, x + side, 13 - (i % 2), C.darkGray)
      }
    }
  }
}

export const rocket: Scene = {
  id: 'rocket',
  loop: LOOP,
  still: 3.4,
  fadesAtLoop: true,
  // A narrow raster keeps Clawd and the pad in view.
  focusX: 19,
  background: (b, time) => drawStarfield(b, time, ['far', 'middle']),
  actors: [
    // The pad and its smoke, a prop behind Clawd (not scenery).
    { kind: 'prop', z: -1, draw: drawPad },
    {
      kind: 'clawd',
      isHero: true,
      at: still(4, CLAWD_TOP),
      look: t => {
        const pop = t - POP
        const isCheering = pop >= 0 && pop < BURST
        const isWatching = t >= FIZZ && !isCheering

        return {
          pose: pop >= 0 && pop < JUMP ? 'jump' : 'stand',
          eyes: t >= FIZZ && t < LIFT + 0.4 ? 'wide' : 'open',
          isBlinking: !isWatching && !isCheering && blinking(t, 0.3),
          look: { x: 1, y: t < LIFT ? 0 : -1 },
          arms: isCheering ? { left: 'up', right: 'up' } : t < FIZZ ? { left: 'down', right: 'out' } : { left: 'down', right: 'down' },
        }
      },
    },
    {
      kind: 'prop',
      z: 1,
      draw: (b, t) => {
        const area = areaOf(b)
        drawTrail(b, t, area)
        if (t < LIFT) {
          // On the pad, fizzing before it goes: the flame flickers on.
          drawShip(b, P0.x, P0.y, SHIPS[0]!, t, t >= FIZZ && every(t, 0.1) % 3 !== 0)
        } else if (t < POP) {
          const s = sOf(t)
          const p = pointAt(s, area)
          drawShip(b, p.x, p.y, shipFor(s, area), t, true)
        }
        drawPop(b, t, area)
      },
    },
  ],
}

