// Treasure map: Clawd unrolls a map, a dotted path runs across it with pins
// popping in along the way to a red X, and he rolls it up again. On a wider
// area the sea lies in the wings, its waves tiled, with a small island; the
// map unrolls as far as ever.

import { fillRect, type PixelBuffer, rightOf, setPixel } from '../pixels'
import { CLAWD_TOP, drawSprite, type Scene, type Sprite, STAGE_W } from '../scene'
import { blinking, C, lerp, still } from './kit'
import { tileOn } from './wings'

const LOOP = 8
const MAP_X = 23
const MAP_Y = 3
const MAP_W = 22
const MAP_H = 9
const UNROLL_FOR = 1.5
const PATH_FROM = 1.5
const PATH_FOR = 3
const ROLL_UP_AT = 6.5
const WAYPOINTS: [number, number][] = [[26, 9], [31, 5], [36, 9], [41, 5]]
// The dots in the order they are drawn: every other pixel along the legs.
const DOTS: [number, number][] = []
for (let i = 1; i < WAYPOINTS.length; i++) {
  const [x0, y0] = WAYPOINTS[i - 1]!
  const [x1, y1] = WAYPOINTS[i]!
  const n = Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0))
  for (let k = 0; k < n; k += 2) DOTS.push([Math.round(x0 + ((x1 - x0) * k) / n), Math.round(y0 + ((y1 - y0) * k) / n)])
}
// A pin pops in at each middle waypoint as the path reaches it; the X at
// the end.
const PINS = [WAYPOINTS[1]!, WAYPOINTS[2]!]
const X_AT = PATH_FROM + PATH_FOR

// How far the map is unrolled, in columns.
const width = (t: number) => Math.round(t < ROLL_UP_AT ? lerp(1, MAP_W, t / UNROLL_FOR) : lerp(MAP_W, 1, (t - ROLL_UP_AT) / (LOOP - ROLL_UP_AT)))

// The sea: rows 11 to 13 from the core's edge to the area's, a wave every
// WAVE_EVERY columns on its top row, still, with a light crest. The island,
// a sandbank with a palm, stands a little way out.
const SEA_Y = 11
const WAVE_EVERY = 6
const ISLAND_X = 62
const ISLAND: Sprite = {
  palette: { g: C.green, t: C.woodDark, s: C.road },
  frames: [['..ggg.....', '.g.t.g....', '....t.....', '....t.....', '..sssss...', 'sssssssss.']],
}

function drawSea(b: PixelBuffer) {
  const edge = rightOf(b)
  if (STAGE_W >= edge) return
  fillRect(b, STAGE_W, SEA_Y + 1, edge - STAGE_W, 2, C.blue)
  tileOn(b, STAGE_W, WAVE_EVERY, x => {
    fillRect(b, x + 1, SEA_Y, 3, 1, C.blue)
    setPixel(b, x + 2, SEA_Y, C.glass)
  })
  drawSprite(b, ISLAND, 0, ISLAND_X, SEA_Y - 4)
}

function drawX(b: PixelBuffer, x: number, y: number) {
  for (const d of [-1, 0, 1]) {
    setPixel(b, x + d, y + d, C.red)
    setPixel(b, x + d, y - d, C.red)
  }
}

export const treasureMap: Scene = {
  id: 'treasure-map',
  loop: LOOP,
  still: 5.2,
  focusX: 28,
  backdrop: drawSea,
  actors: [
    {
      kind: 'clawd',
      isHero: true,
      at: still(7, CLAWD_TOP),
      look: t => ({
        eyes: t >= X_AT && t < X_AT + 0.6 ? 'wide' : 'open',
        isBlinking: blinking(t, 0.9),
        look: { x: 1, y: 0 },
        arms: { left: 'down', right: 'out' },
      }),
    },
  ],
  front: (b, t) => {
    const w = width(t)
    const edge = MAP_X + w
    fillRect(b, MAP_X, MAP_Y, w, MAP_H, C.paper)
    // The two rollers: one in Clawd's claw, one at the unrolled edge.
    fillRect(b, MAP_X - 1, MAP_Y - 1, 1, MAP_H + 2, C.woodDark)
    fillRect(b, edge, MAP_Y - 1, 1, MAP_H + 2, C.woodDark)
    const inside = ([x]: [number, number]) => x < edge - 1
    const drawn = t < PATH_FROM ? 0 : Math.min(DOTS.length, Math.floor(((t - PATH_FROM) / PATH_FOR) * DOTS.length) + 1)
    for (const [x, y] of DOTS.slice(0, drawn).filter(inside)) setPixel(b, x, y, C.ink)
    PINS.forEach((p, i) => {
      if (t < PATH_FROM + ((i + 1) / (WAYPOINTS.length - 1)) * PATH_FOR || !inside(p)) return
      setPixel(b, p[0], p[1] - 2, C.red)
      setPixel(b, p[0], p[1] - 1, C.darkGray)
    })
    const end = WAYPOINTS.at(-1)!
    if (t >= X_AT && inside(end)) drawX(b, end[0], end[1])
  },
}

files.hooks/scenes/victory-lap.ts:
// Victory lap: one of Done's scenes. Under bunting strung across the top,
// Clawd runs a lap of the track with a trophy held out in front: across
// the width, a cheer at the far end with the trophy raised, and back to
// the start, where he raises it again. Behind him, dim stands: the crowd
// rises as he passes, a wave that follows him, and a camera flashes here
// and there while he cheers. On a wider area the lap is longer, up to 150
// columns, at the same few seconds a leg; a taller area shows more of the
// stands.

import { CLAWD_W } from '../clawd'
import { fillRect, type PixelBuffer, setPixel } from '../pixels'
import { type Area, areaOf, CLAWD_TOP, drawSprite, type Scene, type Sprite } from '../scene'
import { blinking, C, every, reach, hash as seededHash } from './kit'
import { eachColumn, fade, wrap } from './layers'

const LOOP = 14
const START_X = 4
const MAX = 150
// The lap's moments: off at GO, at the far end from OUT to BACK, home at
// HOME; a cheer at each end.
const GO = 0.8
const OUT = 5.6
const BACK = 7.6
const HOME = 12.4
// How long a leg's speed takes to build and to drop at its ends, as a
// share of the leg.
const EASE = 0.12

// The bunting: rope rows from the area's top, sagging between hang points
// every SPAN columns; pennants every 3 columns.
const SPAN = 16
const ROPE = fade(C.paper, 0.7)
const PENNANTS = [fade(C.red, 0.3), fade(C.gold, 0.42), fade(C.blue, 0.3), fade(C.green, 0.32)] as const
// The bunting's lowest row, below the area's top.
const BUNTING_H = 3

// The stands: the crowd in tiers, a tier every 3 rows up from the
// barrier, each a dim silhouette (heads over a band of shoulders, a few
// coloured scarves), the higher ones fainter; a tier shows only where its
// standing crowd stays clear of the bunting.
const TIER_HEAD = 7
const TIER_STEP = 3
const TIER_FADE = [0.74, 0.82, 0.88] as const
const SCARVES = [C.red, C.blue, C.green, C.gold] as const
const BARRIER = fade(C.gray, 0.84)
const RAIL = fade(C.paperShade, 0.72)
const TRACK = fade(C.brick, 0.62)
const LANE = fade(C.paper, 0.74)
const FLASH = fade(C.white, 0.2)
// How far behind Clawd's middle the crowd stands up, and how faded the scarves
// it waves are.
const WAVE = 20
const SCARF_FADE = 0.4

const TROPHY: Sprite = { palette: { y: C.gold, w: C.white, d: C.brassDark }, frames: [['ywyyy', 'yyyyy', '.yyy.', '..y..', '.ddd.']] }

// A small hash, for empty seats and shirts.
const hash = (n: number) => seededHash(n, 11)

// A leg's progress, 0 to 1, with its speed building and dropping at the
// ends: a quick start, a steady run, a short slow-down.
function legAt(k: number): number {
  const u = Math.max(0, Math.min(1, k))
  const top = 1 / (1 - EASE)
  if (u < EASE) return (top * u * u) / (2 * EASE)
  if (u > 1 - EASE) return 1 - (top * (1 - u) * (1 - u)) / (2 * EASE)

  return top * (u - EASE / 2)
}

// The lap's length on an area, and Clawd's left column at t.
const lapOf = (area: Area) => reach(area, START_X, MAX, CLAWD_W + 6)
function clawdX(t: number, area: Area): number {
  const lap = lapOf(area)
  if (t < OUT) return Math.round(START_X + lap * legAt((t - GO) / (OUT - GO)))
  if (t < BACK) return START_X + lap
  return Math.round(START_X + lap * (1 - legAt((t - BACK) / (HOME - BACK))))
}
const isRunning = (t: number) => (t >= GO && t < OUT) || (t >= BACK && t < HOME)
const isCheering = (t: number) => (t >= OUT + 0.3 && t < BACK - 0.3) || (t >= HOME + 0.2 && t < LOOP - 0.4)
// Which way he faces: right on the way out and at home, left at the far
// end and on the way back.
const facingAt = (t: number) => (t >= OUT + 0.15 && t < HOME ? -1 : 1)

// The bunting across the top: a rope sagging between hang points, a
// pennant every 3 columns hanging from it, colours in turn, each tip
// fluttering now and then: 40 flutter steps a loop, so it meets itself at
// the loop point.
function drawBunting(b: PixelBuffer, t: number) {
  const top = areaOf(b).top
  eachColumn(b, 0, SPAN, (x, u) => {
    const sag = Math.round(Math.sin((u / SPAN) * Math.PI) * 1.4)
    const y = top + sag
    setPixel(b, x, y, ROPE)
    // A pennant at every third column but the hang point's.
    if (u % 3 !== 2) return
    const i = Math.floor((x + 1000) / 3)
    const color = PENNANTS[wrap(i, PENNANTS.length)]!
    fillRect(b, x - 1, y + 1, 3, 1, color)
    const flutter = wrap(every(t, 0.35) + i * 3, 8) === 0 ? 1 : 0
    setPixel(b, x + flutter, y + 2, color)
  })
}

// Whether the crowd at column x is up: where Clawd has just run past, up
// to WAVE columns behind him, and a few columns ahead; all round him while
// he stands or cheers.
function isStanding(x: number, t: number, middle: number): boolean {
  const ahead = (x - middle) * (isRunning(t) ? facingAt(t) : 1)
  if (!isRunning(t)) return Math.abs(ahead) <= WAVE

  return ahead >= -WAVE && ahead <= CLAWD_W / 2 + 3
}

// The stands: the barrier behind the track, its rail, and above it the
// tiers that fit under the bunting. Near Clawd the crowd stands and waves
// its scarves: a wave that follows him. While he
// cheers a camera flashes at a seat or two away from him.
function drawStands(b: PixelBuffer, t: number) {
  const area = areaOf(b)
  const width = area.right - area.left
  const middle = clawdX(t, area) + CLAWD_W / 2
  const flashOdds = 0.015 * Math.min(1, 120 / width)
  fillRect(b, area.left, 10, width, 1, RAIL)
  fillRect(b, area.left, 11, width, 1, BARRIER)
  // The furthest tier first, so a nearer tier's scarves show over it.
  for (let tier = TIER_FADE.length - 1; tier >= 0; tier--) {
    const head = TIER_HEAD - tier * TIER_STEP
    if (head - 2 < area.top + BUNTING_H + 2) continue
    const k = TIER_FADE[tier]!
    for (let x = area.left; x < area.right; x++) {
      const seat = x * 5 + tier * 977
      fillRect(b, x, head + 1, 1, 2, fade(C.skyShade, k))
      // A head every other column, a seat or so empty.
      const isHead = wrap(x + tier, 2) === 0 && hash(seat) > 0.12
      if (!isHead) continue
      const isUp = isStanding(x, t, middle)
      const scarf = fade(SCARVES[Math.floor(hash(seat + 1) * SCARVES.length)]!, SCARF_FADE)
      // Standing near Clawd: the head a row up, and a scarf waved over it,
      // up and down in turn.
      setPixel(b, x, head - (isUp ? 1 : 0), fade(C.skyShade, k))
      if (isUp) {
        setPixel(b, x, head, fade(C.skyShade, k))
        if (wrap(Math.floor(x / 2) + every(t, 0.25), 2) === 0) setPixel(b, x + 1, head - 2, scarf)
        else setPixel(b, x + 1, head - 1, scarf)
      } else if (hash(seat + 3) < 0.2) setPixel(b, x, head + 1, fade(SCARVES[Math.floor(hash(seat + 1) * SCARVES.length)]!, k - 0.08))
      // A camera's flash, a tenth of a second at a time: as many on a wide
      // area as on 120 columns.
      if (isCheering(t) && Math.abs(x - middle) > CLAWD_W && hash(seat + every(t, 0.1) * 31) < flashOdds) setPixel(b, x, head, FLASH)
    }
  }
}

// The track under Clawd's feet, a dashed lane line along it.
function drawTrack(b: PixelBuffer) {
  eachColumn(b, 0, 6, (x, u) => {
    setPixel(b, x, 12, u < 3 ? LANE : TRACK)
    setPixel(b, x, 13, TRACK)
  })
}

// Clawd's arms: the trophy held out in front while he runs and stands,
// raised in the other claw too while he cheers.
function armsAt(t: number) {
  const facing = facingAt(t)
  if (isCheering(t)) return { left: 'up', right: 'up' } as const

  return facing > 0 ? ({ left: 'down', right: 'out' } as const) : ({ left: 'out', right: 'down' } as const)
}

// The trophy in Clawd's claw: held out in front at the claw's tip, or
// raised over his shoulder while he cheers.
function drawTrophy(b: PixelBuffer, t: number) {
  const x = clawdX(t, areaOf(b))
  const facing = facingAt(t)
  if (isCheering(t)) {
    const side = facing > 0 ? x + CLAWD_W - 3 : x - 2
    drawSprite(b, TROPHY, 0, side, CLAWD_TOP - 3)

    return
  }
  // The claw's tip, held out: 2 columns past the body on its side.
  const tip = facing > 0 ? x + CLAWD_W + 1 : x - 2
  const bob = isRunning(t) && every(t, 0.12) % 2 === 1 ? 1 : 0
  drawSprite(b, TROPHY, 0, tip - 2, CLAWD_TOP - 1 + bob)
}

export const victoryLap: Scene = {
  id: 'victory-lap',
  loop: LOOP,
  still: 6.6,
  focusX: START_X + 7,
  // The camera follows Clawd round the lap.
  focus: (t, area) => clawdX(t, area) + 7,
  backdrop: (b, t) => {
    drawBunting(b, t)
    drawStands(b, t)
    drawTrack(b)
  },
  actors: [
    // Behind Clawd, so his claw grips it in front.
    { kind: 'prop', z: -1, draw: drawTrophy },
    {
      kind: 'clawd',
      isHero: true,
      at: (t, area) => ({ x: clawdX(t, area), y: CLAWD_TOP }),
      look: t => ({
        pose: isRunning(t) ? 'walk' : 'stand',
        stride: every(t, 0.09),
        facing: facingAt(t),
        eyes: isCheering(t) ? 'wide' : 'open',
        isBlinking: !isRunning(t) && !isCheering(t) && blinking(t, 0.6),
        look: { x: facingAt(t), y: isCheering(t) ? -1 : 0 },
        arms: armsAt(t),
      }),
    },
  ],
}

files.hooks/scenes/waiting-bench.ts:
// Waiting bench: Clawd sits on a bench while a clock ticks, and now and
// then turns and waves at you. On a wider area the bench runs on to the
// edge; a "now serving" display on the wall counts up the tickets, and
// along the bench, again and again, a water cooler and a potted plant
// stand.

import { fillRect, type PixelBuffer, rightOf, setPixel } from '../pixels'
import { drawSprite, type Scene, type Sprite } from '../scene'
import { blinking, C, every, still } from './kit'
import { tileOn, WINGS_X } from './wings'

const LOOP = 8
const WAVE_FROM = 4
const WAVE_TO = 5.6
// The wall clock: a round face 9 pixels across, a gray rim round a paper
// face, ticks at 12, 3, 6 and 9, and one hand going round.
const CLOCK = { x: 39, y: 5 }
// The rim, row by row from the top: each row's dx values.
const RIM_ROWS: number[][] = [[-1, 0, 1], [-3, -2, 2, 3], [-3, 3], [-4, 4], [-4, 4], [-4, 4], [-3, 3], [-3, -2, 2, 3], [-1, 0, 1]]
// The face inside it: each row's half width, from dy -3 to 3.
const FACE_HALF = [1, 2, 3, 3, 3, 2, 1]
const TICKS: [number, number][] = [[0, -3], [3, 0], [0, 3], [-3, 0]]
// The hand's tip in eight steps from twelve o'clock; two turns a loop.
const HAND: [number, number][] = [[0, -2], [2, -2], [2, 0], [2, 2], [0, 2], [-2, 2], [-2, 0], [-2, -2]]

function drawClock(b: PixelBuffer, t: number) {
  RIM_ROWS.forEach((xs, i) => xs.forEach(dx => setPixel(b, CLOCK.x + dx, CLOCK.y - 4 + i, C.gray)))
  FACE_HALF.forEach((half, i) => fillRect(b, CLOCK.x - half, CLOCK.y - 3 + i, 2 * half + 1, 1, C.paper))
  for (const [dx, dy] of TICKS) setPixel(b, CLOCK.x + dx, CLOCK.y + dy, C.darkGray)
  const [hx, hy] = HAND[every(t, 0.5) % HAND.length]!
  setPixel(b, CLOCK.x, CLOCK.y, C.ink)
  setPixel(b, CLOCK.x + Math.sign(hx), CLOCK.y + Math.sign(hy), C.ink)
  setPixel(b, CLOCK.x + hx, CLOCK.y + hy, C.ink)
}

// The wings, every ROOM_EVERY columns (three of the bench's legs) from the
// core's edge: the cooler and the plant standing on the floor in front of
// the bench, each only where it fits whole; and in the first room alone,
// the display on the wall, rows 2 to 8.
const ROOM_EVERY = 51
const DISPLAY_X = 3
const COOLER_X = 19
const PLANT_X = 35
// The display shows a ticket number in 3 x 5 digits, red on a dark
// screen. It counts up one every TICKET_EVERY seconds of the scene's
// unwrapped time, from FIRST_TICKET, round from 99 to 00: never back at
// the loop point.
const TICKET_EVERY = 3
const FIRST_TICKET = 42
const DIGITS = ['111101101101111', '010110010010111', '111001111100111', '111001111001111', '101101111001001', '111100111001111', '111100111101111', '111001010010010', '111101111101111', '111101111001111']
export const ticketAt = (time: number): number => (FIRST_TICKET + every(Math.max(0, time), TICKET_EVERY)) % 100
const COOLER: Sprite = {
  palette: { g: C.glass, b: C.blue, s: C.paperShade, d: C.darkGray, r: C.red },
  frames: [['.ggg.', '.bbb.', '.bbb.', '..g..', 'sssss', 'sdsrs', 'sssss', 'sssss', 'sssss', 'sssss', 'd...d']],
}
const PLANT: Sprite = {
  palette: { g: C.green, p: C.brick },
  frames: [['..g..', 'g.g.g', '.ggg.', 'g.g.g', '.ggg.', '..g..', 'ppppp', '.ppp.', '.ppp.']],
}

function drawDisplay(b: PixelBuffer, time: number) {
  const ticket = ticketAt(time)
  const digits = [Math.floor(ticket / 10), ticket % 10]
  const d = WINGS_X + DISPLAY_X
  if (d + 11 > rightOf(b)) return
  fillRect(b, d, 2, 11, 7, C.darkGray)
  fillRect(b, d + 1, 3, 9, 5, C.ink)
  digits.forEach((n, i) => {
    for (let p = 0; p < 15; p++) if (DIGITS[n]![p] === '1') setPixel(b, d + 1 + 4 * i + (p % 3) + 1, 3 + Math.floor(p / 3), C.red)
  })
}

export const waitingBench: Scene = {
  id: 'waiting-bench',
  loop: LOOP,
  still: 2,
  focusX: 24,
  // The display counts on the scene's unwrapped time.
  background: drawDisplay,
  backdrop: b => {
    fillRect(b, 6, 11, 22, 1, C.wood)
    fillRect(b, 8, 12, 1, 2, C.woodDark)
    fillRect(b, 25, 12, 1, 2, C.woodDark)
    // It ends at 27 on 48 columns; on a wider area it runs on from 28, a leg
    // every 17 columns after its right one (25), as far apart as its own.
    const edge = rightOf(b)
    if (edge <= 48) return
    fillRect(b, 28, 11, edge - 28, 1, C.wood)
    for (let x = 25 + 17; x < edge; x += 17) fillRect(b, x, 12, 1, 2, C.woodDark)
    tileOn(b, WINGS_X, ROOM_EVERY, x => {
      if (x + COOLER_X + 5 <= edge) drawSprite(b, COOLER, 0, x + COOLER_X, 3)
      if (x + PLANT_X + 5 <= edge) drawSprite(b, PLANT, 0, x + PLANT_X, 5)
    })
  },
  actors: [
    {
      kind: 'clawd',
      isHero: true,
      // Sitting, Clawd's body drops 2 pixels: at y 3 it rests on the seat (row 11).
      at: still(11, 3),
      look: t => {
        const isWaving = t >= WAVE_FROM && t < WAVE_TO

        return {
          pose: 'sit',
          isBlinking: blinking(t, 0.8),
          look: isWaving ? { x: 0, y: 1 } : { x: 1, y: -1 },
          arms: { left: 'down', right: isWaving ? (every(t, 0.25) % 2 === 0 ? 'up' : 'out') : 'down' },
        }
      },
    },
  ],
  front: drawClock,
}

